// AUTO-GENERATED by scripts/build-api-docs.mjs from /docs. Do not edit; run `npm run gen:docs -w aaira-gallery`.
const area: Record<string, Record<string, string>> = {"asp-net-typescript-mapping":{"overview":"<div class=\"table-scroll\"><table><thead><tr><th>ASP.NET Web Forms</th><th>TypeScript (<code>@wf-controls/core</code>)</th><th>Notes</th></tr></thead><tbody><tr><td><code>&lt;asp:Login&gt;</code></td><td><code>LoginController</code></td><td><code>OnLoggingIn</code> / <code>OnLoggedIn</code> / <code>OnLoginError</code> become <code>loggingIn</code> / <code>loggedIn</code> / <code>loginError</code>. No <code>OnAuthenticate</code> event (see 2.2).</td></tr><tr><td><code>&lt;asp:LoginView&gt;</code></td><td><code>LoginViewController&lt;T&gt;</code></td><td><code>AnonymousTemplate</code>, <code>LoggedInTemplate</code>, <code>RoleGroups</code> map to constructor options; templates are opaque values of type <code>T</code>.</td></tr><tr><td><code>&lt;asp:LoginStatus&gt;</code></td><td><code>LoginStatusController</code></td><td><code>OnLoggingOut</code> / <code>OnLoggedOut</code> become <code>loggingOut</code> / <code>loggedOut</code>.</td></tr><tr><td><code>&lt;asp:LoginName&gt;</code></td><td><code>LoginNameController</code></td><td><code>FormatString</code> with <code>{0}</code>.</td></tr><tr><td><code>&lt;asp:ChangePassword&gt;</code></td><td><code>ChangePasswordController</code></td><td><code>OnChangingPassword</code> / <code>OnChangedPassword</code> / <code>OnChangePasswordError</code> / <code>OnContinueButtonClick</code>.</td></tr><tr><td><code>&lt;asp:PasswordRecovery&gt;</code></td><td><code>PasswordRecoveryController</code></td><td><code>OnVerifyingUser</code> / <code>OnVerifyingAnswer</code> / <code>OnSendingMail</code> / <code>OnUserLookupError</code> / <code>OnAnswerLookupError</code>.</td></tr><tr><td><code>&lt;asp:CreateUserWizard&gt;</code></td><td><code>CreateUserWizardController</code></td><td><code>OnCreatingUser</code> / <code>OnCreatedUser</code> / <code>OnCreateUserError</code> / <code>OnContinueButtonClick</code>.</td></tr><tr><td><code>MembershipProvider</code></td><td><code>IMembershipProvider</code></td><td>Async (<code>Promise</code>) except <code>getCurrentUser</code>, <code>isInRole</code>, <code>getRolesForUser</code>.</td></tr><tr><td><code>Membership.Provider</code> / <code>FormsAuthentication</code></td><td><code>SecurityManager</code></td><td>Static default-provider holder + <code>currentUserChanged</code> broadcaster.</td></tr><tr><td><code>MembershipUser</code></td><td><code>IUser</code></td><td>Plain object.</td></tr><tr><td><code>MembershipCreateStatus</code></td><td><code>MembershipCreateStatus</code></td><td>String-literal union.</td></tr><tr><td><code>Roles.IsUserInRole</code></td><td><code>IMembershipProvider.isInRole</code></td><td>Synchronous.</td></tr><tr><td><code>CancelEventArgs</code></td><td><code>CancelEventArgs</code> (<code>{ cancel: boolean }</code>)</td><td>Set <code>args.cancel = true</code> in a handler.</td></tr><tr><td>(ViewState / Session / auth cookie)</td><td>Provider-owned in-memory field</td><td>No cookie, no <code>localStorage</code>, no persistence built in.</td></tr></tbody></table></div>\n<hr>\n"},"quick-start":{"overview":"<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">import</span> { <span class=\"tok-t\">LoginController</span>, <span class=\"tok-t\">SecurityManager</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n\n<span class=\"tok-c\">// The built-in default provider is an InMemoryAuthProvider seeded with two demo users:</span>\n<span class=\"tok-c\">//   admin / Password123!  roles: Administrators, Users</span>\n<span class=\"tok-c\">//   user  / Password123!  roles: Users</span>\n<span class=\"tok-k\">const</span> login = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginController</span>({ id: <span class=\"tok-s\">&quot;Login1&quot;</span> });\n\nlogin.loggingIn.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;loggingIn&quot;</span>, e.userName, e.rememberMe, e.cancel));\nlogin.loggedIn.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;loggedIn&quot;</span>, e.userName, e.user.roles));\nlogin.loginError.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;loginError&quot;</span>, e.errorMessage));\n\nlogin.<span class=\"tok-f\">setUserName</span>(<span class=\"tok-s\">&quot;admin&quot;</span>);\nlogin.<span class=\"tok-f\">setPassword</span>(<span class=\"tok-s\">&quot;wrong&quot;</span>);\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> login.<span class=\"tok-f\">login</span>(), login.failureMessage);\n<span class=\"tok-c\">// -&gt; loggingIn admin false false</span>\n<span class=\"tok-c\">// -&gt; loginError Your login attempt was not successful. Please try again.</span>\n<span class=\"tok-c\">// -&gt; false Your login attempt was not successful. Please try again.</span>\n\nlogin.<span class=\"tok-f\">setPassword</span>(<span class=\"tok-s\">&quot;Password123!&quot;</span>);\nlogin.<span class=\"tok-f\">setRememberMe</span>(<span class=\"tok-k\">true</span>);\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> login.<span class=\"tok-f\">login</span>(), login.isLoggedIn, <span class=\"tok-t\">JSON</span>.<span class=\"tok-f\">stringify</span>(login.password), login.isVisible);\n<span class=\"tok-c\">// -&gt; loggingIn admin true false</span>\n<span class=\"tok-c\">// -&gt; loggedIn admin [ 'Administrators', 'Users' ]</span>\n<span class=\"tok-c\">// -&gt; true true &quot;&quot; false          (password is cleared after success; Login hides itself)</span>\n\n<span class=\"tok-k\">await</span> <span class=\"tok-t\">SecurityManager</span>.defaultProvider.<span class=\"tok-f\">logout</span>();</code></pre></div>\n<blockquote class=\"\"><p><strong>Demo-only warning.</strong> The default provider and <code>InMemoryAuthProvider</code> store passwords as <strong>plain text</strong> in a JavaScript <code>Map</code>, with no hashing, no salting, no persistence. They exist for demos, prototypes, and unit tests. Production code must register a provider that talks to a real identity backend (section 11).</p></blockquote>\n<hr>\n"},"authentication-flow-exact-behaviour":{"roles-of-the-pieces":"<h3 id=\"21-roles-of-the-pieces\">2.1 Roles of the pieces<a class=\"anchor\" href=\"#21-roles-of-the-pieces\" aria-label=\"Link to this section\">#</a></h3>\n<ul><li><code>LoginController</code> collects credentials and orchestrates events.</li><li>The <strong>provider</strong> decides whether credentials are valid <em>and</em> owns the &quot;current user&quot; (the session).</li><li><code>SecurityManager.currentUserChanged</code> is a global <code>EventDispatcher&lt;IMembershipProvider, IUser | null&gt;</code> that tells <code>LoginView</code>, <code>LoginStatus</code>, and <code>LoginName</code> to refresh.</li></ul>\n","logincontroller-login-step-by-step":"<h3 id=\"22-logincontrollerlogin-step-by-step\">2.2 <code>LoginController.login()</code> step by step<a class=\"anchor\" href=\"#22-logincontrollerlogin-step-by-step\" aria-label=\"Link to this section\">#</a></h3>\n<ol><li><code>failureMessage</code> is reset to <code>null</code>.</li><li><code>validate()</code> runs. Both <code>userName</code> (non-blank after trim) and <code>password</code> (non-empty) are required. If it fails: <code>validationErrors</code> is filled, <code>stateChanged</code> is emitted, and <code>login()</code> resolves <code>false</code>. <strong>No <code>loggingIn</code>/<code>loginError</code> event fires and <code>failureMessage</code> stays <code>null</code>.</strong></li><li><code>loggingIn</code> is raised with a <code>LoginCancelEventArgs</code> (<code>userName</code>, <code>password</code>, <code>rememberMe</code>, <code>cancel: false</code>). Handlers run sequentially and are awaited. If any handler sets <code>cancel = true</code>, <code>login()</code> resolves <code>false</code> <strong>silently</strong>: no <code>loginError</code>, no <code>failureMessage</code>, no <code>stateChanged</code>, provider not called.</li><li><code>provider.login(userName, password, rememberMeSet)</code> is awaited. (This is the only provider call; <code>LoginController.login()</code> does <strong>not</strong> call <code>authenticate()</code> or <code>validateUser()</code> itself. There is no separate <code>authenticate</code> event in this implementation. The ASP.NET <code>OnAuthenticate</code> step is folded into <code>provider.login</code>.)</li><li>On success: <code>failureMessage = null</code>, <code>password = &quot;&quot;</code>, <code>loggedIn</code> is raised with <code>{ userName, user }</code> (where <code>user = provider.getCurrentUser()</code>), then <code>stateChanged</code>, resolves <code>true</code>.</li><li>On failure: <code>failureMessage = failureText</code>, <code>loginError</code> is raised with <code>{ userName, errorMessage: failureText }</code>, then <code>stateChanged</code>, resolves <code>false</code>. The password field is <strong>not</strong> cleared on failure.</li></ol>\n<p>Event order: <code>loggingIn</code> -&gt; (provider login) -&gt; <code>loggedIn</code> <strong>or</strong> <code>loginError</code> -&gt; <code>stateChanged</code>.</p>\n<p>The failure message is deliberately generic: wrong password, unknown user, locked-out user, and unapproved user are indistinguishable to the caller.</p>\n","cancel-semantics":"<h3 id=\"23-cancel-semantics\">2.3 Cancel semantics<a class=\"anchor\" href=\"#23-cancel-semantics\" aria-label=\"Link to this section\">#</a></h3>\n<p>Only events whose args extend <code>CancelEventArgs</code> can be cancelled: <code>loggingIn</code>, <code>loggingOut</code>, <code>changingPassword</code>, <code>verifyingUser</code>, <code>verifyingAnswer</code>, <code>sendingMail</code>, <code>creatingUser</code>. Cancelling resolves the operation with <code>false</code>, skips every later step, and emits no error event.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> login = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginController</span>({ userName: <span class=\"tok-s\">&quot;admin&quot;</span>, password: <span class=\"tok-s\">&quot;Password123!&quot;</span> });\nlogin.loggingIn.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; { e.cancel = <span class=\"tok-k\">true</span>; });\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> login.<span class=\"tok-f\">login</span>(), login.isLoggedIn, login.failureMessage);\n<span class=\"tok-c\">// -&gt; false false null</span></code></pre></div>\n","remember-me":"<h3 id=\"24-remember-me\">2.4 Remember me<a class=\"anchor\" href=\"#24-remember-me\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>rememberMeSet</code> / <code>setRememberMe()</code> is only <strong>forwarded</strong> as the third argument of <code>provider.login()</code> and as <code>rememberMe</code> in <code>loggingIn</code> args. <code>InMemoryAuthProvider</code> ignores it (the parameter is <code>_rememberMe</code>). Persisting a session across reloads (cookie, <code>localStorage</code>, token refresh) is entirely the provider's job.</p>\n","session-current-user-storage":"<h3 id=\"25-session--current-user-storage\">2.5 Session / current user storage<a class=\"anchor\" href=\"#25-session--current-user-storage\" aria-label=\"Link to this section\">#</a></h3>\n<ul><li>There is no controller-level session. <code>LoginController.currentUser</code>, <code>isLoggedIn</code>, <code>isAuthenticated</code> all read <code>provider.getCurrentUser()</code> live.</li><li><code>InMemoryAuthProvider</code> keeps the session in a private <code>currentUser</code> field (a clone of the stored user). It is lost on page reload and is <strong>per provider instance</strong>.</li><li><code>InMemoryAuthProvider.login</code> / <code>logout</code> call <code>SecurityManager.notifyCurrentUserChanged(...)</code>. A custom provider <strong>must do the same</strong> or <code>LoginView</code>, <code>LoginStatus</code>, <code>LoginName</code> will never refresh (they subscribe to the global dispatcher, not to the provider).</li></ul>\n","role-checks-and-loginview-template-switching":"<h3 id=\"26-role-checks-and-loginview-template-switching\">2.6 Role checks and LoginView template switching<a class=\"anchor\" href=\"#26-role-checks-and-loginview-template-switching\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>LoginViewController.resolveActiveView()</code> evaluates in this order:</p>\n<ol><li>No current user -&gt; <code>{ type: &quot;Anonymous&quot;, template: anonymousTemplate, user: null }</code>.</li><li>For each <code>roleGroups[i]</code> in order, for each role in <code>roleGroups[i].roles</code> in order: if the user's <code>roles</code> contain it (case-insensitive) -&gt; <code>{ type: &quot;RoleGroup&quot;, template, matchedRole, matchedRoleGroupIndex: i, user }</code>. <strong>First match wins</strong>, so order groups from most to least specific.</li><li>Otherwise -&gt; <code>{ type: &quot;LoggedIn&quot;, template: loggedInTemplate, user }</code>.</li></ol>\n<p>Roles are read from <code>user.roles</code> (the <code>IUser</code> snapshot), not from <code>provider.isInRole</code>.</p>\n","authenticate-is-not-login":"<h3 id=\"27-authenticate-is-not-login\">2.7 <code>authenticate()</code> is not login<a class=\"anchor\" href=\"#27-authenticate-is-not-login\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>LoginController.authenticate()</code> just returns <code>provider.validateUser(userName, password)</code>. It creates no session, and (with <code>InMemoryAuthProvider</code>) still increments the failed-attempt counter on a bad password.</p>\n<hr>\n"},"imembershipprovider-and-related-types":{"overview":"<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">export</span> <span class=\"tok-k\">interface</span> <span class=\"tok-t\">IUser</span> {\n  userName: string;\n  email?: string | <span class=\"tok-k\">undefined</span>;\n  roles?: string[] | <span class=\"tok-k\">undefined</span>;\n  isLockedOut?: boolean | <span class=\"tok-k\">undefined</span>;\n  isApproved?: boolean | <span class=\"tok-k\">undefined</span>;\n  lastLoginDate?: <span class=\"tok-t\">Date</span> | <span class=\"tok-k\">undefined</span>;\n  passwordQuestion?: string | <span class=\"tok-k\">undefined</span>;\n  customData?: <span class=\"tok-t\">Record</span>&lt;string, unknown&gt; | <span class=\"tok-k\">undefined</span>;\n}\n\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">type</span> <span class=\"tok-t\">MembershipCreateStatus</span> =\n  | <span class=\"tok-s\">&quot;Success&quot;</span> | <span class=\"tok-s\">&quot;InvalidUserName&quot;</span> | <span class=\"tok-s\">&quot;InvalidPassword&quot;</span> | <span class=\"tok-s\">&quot;InvalidQuestion&quot;</span> | <span class=\"tok-s\">&quot;InvalidAnswer&quot;</span>\n  | <span class=\"tok-s\">&quot;InvalidEmail&quot;</span> | <span class=\"tok-s\">&quot;DuplicateUserName&quot;</span> | <span class=\"tok-s\">&quot;DuplicateEmail&quot;</span> | <span class=\"tok-s\">&quot;UserRejected&quot;</span> | <span class=\"tok-s\">&quot;ProviderError&quot;</span>;\n\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">interface</span> <span class=\"tok-t\">MembershipCreateResult</span> {\n  status: <span class=\"tok-t\">MembershipCreateStatus</span>;\n  user?: <span class=\"tok-t\">IUser</span> | <span class=\"tok-k\">undefined</span>;\n  errorMessage?: string | <span class=\"tok-k\">undefined</span>;\n}</code></pre></div>\n","iuser":"<h3 id=\"31-iuser\">3.1 <code>IUser</code><a class=\"anchor\" href=\"#31-iuser\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>userName</code></td><td><code>string</code></td><td>Required. Unique key (providers compare case-insensitively).</td></tr><tr><td><code>email</code></td><td><code>string | undefined</code></td><td>Used for duplicate-email detection and <code>PasswordRecovery</code> mail args.</td></tr><tr><td><code>roles</code></td><td><code>string[] | undefined</code></td><td>Role names. <code>LoginView</code> and <code>isInRole</code> compare case-insensitively.</td></tr><tr><td><code>isLockedOut</code></td><td><code>boolean | undefined</code></td><td><code>PasswordRecovery</code> refuses locked users.</td></tr><tr><td><code>isApproved</code></td><td><code>boolean | undefined</code></td><td>Unapproved users cannot log in (InMemory).</td></tr><tr><td><code>lastLoginDate</code></td><td><code>Date | undefined</code></td><td>Set by <code>InMemoryAuthProvider.login</code>.</td></tr><tr><td><code>passwordQuestion</code></td><td><code>string | undefined</code></td><td>Shown by <code>PasswordRecovery</code>.</td></tr><tr><td><code>customData</code></td><td><code>Record&lt;string, unknown&gt; | undefined</code></td><td>Free-form extra data (shallow-copied by InMemory).</td></tr></tbody></table></div>\n","membershipcreatestatus-membershipcreateresult":"<h3 id=\"32-membershipcreatestatus--membershipcreateresult\">3.2 <code>MembershipCreateStatus</code> / <code>MembershipCreateResult</code><a class=\"anchor\" href=\"#32-membershipcreatestatus--membershipcreateresult\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>CreateUserWizardController</code> treats only <code>status === &quot;Success&quot;</code> <strong>with</strong> a <code>user</code> as success. Any other status is a failure. It special-cases three statuses for message text: <code>DuplicateUserName</code>, <code>DuplicateEmail</code>, <code>InvalidPassword</code>; every other status shows <code>result.errorMessage ?? &quot;An error occurred creating the user.&quot;</code>. <code>InMemoryAuthProvider</code> only ever returns <code>Success</code>, <code>InvalidUserName</code>, <code>InvalidPassword</code>, <code>DuplicateUserName</code>, <code>DuplicateEmail</code>. The other statuses are available to custom providers.</p>\n","imembershipprovider-contract":"<h3 id=\"33-imembershipprovider-contract\">3.3 <code>IMembershipProvider</code> contract<a class=\"anchor\" href=\"#33-imembershipprovider-contract\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Member</th><th>Signature</th><th>Contract</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>readonly name: string</code></td><td>Display/identification name.</td></tr><tr><td><code>validateUser</code></td><td><code>(userName: string, password: string) =&gt; Promise&lt;boolean&gt;</code></td><td>Check credentials <strong>without</strong> creating a session. Resolve <code>false</code> (do not reject) for bad credentials.</td></tr><tr><td><code>getUser</code></td><td><code>(userName: string) =&gt; Promise&lt;IUser | null&gt;</code></td><td>Look a user up. <code>null</code> if unknown. Used by <code>PasswordRecovery</code> (existence, lock state, email).</td></tr><tr><td><code>getCurrentUser</code></td><td><code>() =&gt; IUser | null</code></td><td><strong>Synchronous.</strong> The logged-in user or <code>null</code>. Called on every property read of every control: it must be cheap and must not hit the network. Return a copy.</td></tr><tr><td><code>createUser</code></td><td><code>(userName, password, email?, passwordQuestion?, passwordAnswer?, isApproved?) =&gt; Promise&lt;MembershipCreateResult&gt;</code></td><td>Create a user. Report problems with <code>status</code>, not by throwing. Must not log the user in.</td></tr><tr><td><code>changePassword</code></td><td><code>(userName, oldPassword, newPassword) =&gt; Promise&lt;boolean&gt;</code></td><td><code>false</code> on wrong old password or policy violation.</td></tr><tr><td><code>resetPassword</code></td><td><code>(userName, answer?) =&gt; Promise&lt;string | null&gt;</code></td><td>Return the new temporary password, or <code>null</code> on failure (unknown/locked user, wrong answer).</td></tr><tr><td><code>getPasswordQuestion</code></td><td><code>(userName) =&gt; Promise&lt;string | null&gt;</code></td><td>Question to challenge with, or <code>null</code>.</td></tr><tr><td><code>unlockUser</code></td><td><code>(userName) =&gt; Promise&lt;boolean&gt;</code></td><td><code>true</code> if the user existed and was unlocked. Not called by any built-in controller.</td></tr><tr><td><code>login</code></td><td><code>(userName, password, rememberMe?) =&gt; Promise&lt;boolean&gt;</code></td><td>Validate <strong>and</strong> establish the session so <code>getCurrentUser()</code> returns the user. Must call <code>SecurityManager.notifyCurrentUserChanged(user)</code>.</td></tr><tr><td><code>logout</code></td><td><code>() =&gt; Promise&lt;void&gt;</code></td><td>Clear the session and call <code>SecurityManager.notifyCurrentUserChanged(null)</code>.</td></tr><tr><td><code>isInRole</code></td><td><code>(role: string, userName?: string) =&gt; boolean</code></td><td><strong>Synchronous.</strong> <code>userName</code> omitted -&gt; current user.</td></tr><tr><td><code>getRolesForUser</code></td><td><code>(userName?: string) =&gt; string[]</code></td><td><strong>Synchronous.</strong> <code>userName</code> omitted -&gt; current user. Empty array if none.</td></tr></tbody></table></div>\n<p>Rules a custom provider must follow:</p>\n<ol><li>Resolve <code>false</code>/<code>null</code> for expected failures; the controllers do not <code>try/catch</code> provider calls, so a rejection propagates out of <code>login()</code>, <code>changePassword()</code>, etc. as a rejected promise (no error event fires).</li><li>After <code>login()</code> resolves <code>true</code>, <code>getCurrentUser()</code> must return a non-null user; <code>LoginController</code> reads it with a non-null assertion.</li><li>Call <code>SecurityManager.notifyCurrentUserChanged()</code> on every session change.</li><li><code>getCurrentUser</code>, <code>isInRole</code>, <code>getRolesForUser</code> are synchronous: cache what you need at login time.</li></ol>\n<p>A full REST example is in section 11.</p>\n<hr>\n"},"inmemoryauthprovider":{"overview":"<p>In-memory <code>IMembershipProvider</code> implementation. <strong>Plain-text passwords. Demo / test use only.</strong></p>\n<p>ASP.NET equivalent: none exact (closest: a test double for <code>SqlMembershipProvider</code>).</p>\n","constructor-options-inmemoryauthprovideroptions":"<h3 id=\"41-constructor-options-inmemoryauthprovideroptions\">4.1 Constructor options (<code>InMemoryAuthProviderOptions</code>)<a class=\"anchor\" href=\"#41-constructor-options-inmemoryauthprovideroptions\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code></td><td><code>&quot;InMemoryAuthProvider&quot;</code></td><td>Provider name.</td></tr><tr><td><code>maxInvalidPasswordAttempts</code></td><td><code>number</code></td><td><code>5</code></td><td>Consecutive failed <code>validateUser</code> calls before the user is locked out.</td></tr><tr><td><code>users</code></td><td><code>SeedUser[]</code></td><td>none</td><td>Seed users. <code>SeedUser</code> = <code>IUser</code> + <code>password: string</code> + <code>passwordAnswer?: string</code>. Roles default <code>[]</code>, <code>isLockedOut</code> <code>false</code>, <code>isApproved</code> <code>true</code>. Keys are <code>userName.toLowerCase()</code> (not trimmed).</td></tr></tbody></table></div>\n","properties":"<h3 id=\"42-properties\">4.2 Properties<a class=\"anchor\" href=\"#42-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code></td><td>r</td><td>see above</td><td>Provider name.</td></tr></tbody></table></div>\n","methods":"<h3 id=\"43-methods\">4.3 Methods<a class=\"anchor\" href=\"#43-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>validateUser(userName: string, password: string): Promise&lt;boolean&gt;</code></td><td>Case-insensitive user lookup. <code>false</code> for unknown, locked-out, or unapproved users (without touching counters). On exact (case-sensitive) password match resets the failure counter and returns <code>true</code>. Otherwise increments the counter, locks the user when <code>counter &gt;= maxInvalidPasswordAttempts</code>, returns <code>false</code>.</td></tr><tr><td><code>getUser(userName: string): Promise&lt;IUser | null&gt;</code></td><td>Clone of the user (no password/answer) or <code>null</code>.</td></tr><tr><td><code>getCurrentUser(): IUser | null</code></td><td>Clone of the session user or <code>null</code>.</td></tr><tr><td><code>createUser(userName, password, email?, passwordQuestion?, passwordAnswer?, isApproved = true): Promise&lt;MembershipCreateResult&gt;</code></td><td>See policy below. New users get <code>roles: [&quot;User&quot;]</code>.</td></tr><tr><td><code>changePassword(userName, oldPassword, newPassword): Promise&lt;boolean&gt;</code></td><td><code>false</code> if user unknown, <code>oldPassword</code> mismatch, or <code>newPassword</code> empty/shorter than 4. Does not check lock-out.</td></tr><tr><td><code>resetPassword(userName, answer?): Promise&lt;string | null&gt;</code></td><td><code>null</code> if unknown or locked. If the user has a stored answer, <code>answer</code> must match (trimmed, case-insensitive) else <code>null</code>. If the user has <strong>no</strong> stored answer, any/no answer works. On success sets the password to <code>Temp#&lt;6 random base36 chars&gt;!</code> and clears the failure counter. Uses <code>Math.random</code> (not cryptographically secure).</td></tr><tr><td><code>getPasswordQuestion(userName): Promise&lt;string | null&gt;</code></td><td>The stored question or <code>null</code>.</td></tr><tr><td><code>unlockUser(userName): Promise&lt;boolean&gt;</code></td><td><code>false</code> if unknown; else clears <code>isLockedOut</code> and the counter, <code>true</code>.</td></tr><tr><td><code>login(userName, password, _rememberMe = false): Promise&lt;boolean&gt;</code></td><td><code>validateUser</code>, then sets <code>lastLoginDate = new Date()</code>, stores a clone as the session user, calls <code>SecurityManager.notifyCurrentUserChanged(user)</code>. <code>rememberMe</code> ignored.</td></tr><tr><td><code>logout(): Promise&lt;void&gt;</code></td><td>Clears the session; <code>notifyCurrentUserChanged(null)</code>. Safe when nobody is logged in (still notifies).</td></tr><tr><td><code>isInRole(role: string, userName?: string): boolean</code></td><td>Case-insensitive. Uses session user when <code>userName</code> omitted; <code>false</code> if none. Looks roles up in the <strong>stored</strong> record.</td></tr><tr><td><code>getRolesForUser(userName?: string): string[]</code></td><td>Copy of roles; <code>[]</code> if no user.</td></tr></tbody></table></div>\n","password-policy-and-security-behaviour-what-is-actually-enforced":"<h3 id=\"44-password-policy-and-security-behaviour-what-is-actually-enforced\">4.4 Password policy and security behaviour (what is actually enforced)<a class=\"anchor\" href=\"#44-password-policy-and-security-behaviour-what-is-actually-enforced\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Rule</th><th>Enforced where</th></tr></thead><tbody><tr><td>Password length &gt;= 4</td><td><code>createUser</code> (<code>InvalidPassword</code>), <code>changePassword</code> (returns <code>false</code>).</td></tr><tr><td>No complexity / digit / symbol rules</td><td>Not enforced by the provider.</td></tr><tr><td>Blank/whitespace user name rejected</td><td><code>createUser</code> (<code>InvalidUserName</code>).</td></tr><tr><td>Duplicate user name (case-insensitive, trimmed)</td><td><code>createUser</code> -&gt; <code>DuplicateUserName</code>.</td></tr><tr><td>Duplicate email (case-insensitive)</td><td><code>createUser</code> -&gt; <code>DuplicateEmail</code>. Email format is <strong>not</strong> validated.</td></tr><tr><td>Question/answer validity</td><td>Not validated (<code>InvalidQuestion</code>, <code>InvalidAnswer</code>, <code>InvalidEmail</code> are never returned).</td></tr><tr><td>Lock-out after N bad passwords</td><td><code>validateUser</code> (hence <code>login</code>, <code>LoginController.authenticate</code>). Lock persists until <code>unlockUser</code> is called (<code>resetPassword</code> refuses locked users).</td></tr><tr><td>Unapproved user</td><td>Cannot log in (<code>validateUser</code> returns <code>false</code>); <code>createUser(..., isApproved=false)</code>.</td></tr><tr><td>Password storage</td><td><strong>Plain text in a <code>Map</code>. No hashing.</strong> Comparison is <code>===</code>.</td></tr><tr><td>Persistence</td><td>None. Everything is lost on reload/new instance.</td></tr><tr><td>Reads are defensive copies</td><td><code>getUser</code>, <code>getCurrentUser</code>, <code>getRolesForUser</code> return clones; mutating them does not change stored data.</td></tr></tbody></table></div>\n<p>Verified:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> p = <span class=\"tok-k\">new</span> <span class=\"tok-t\">InMemoryAuthProvider</span>();\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">createUser</span>(<span class=\"tok-s\">&quot;  &quot;</span>, <span class=\"tok-s\">&quot;abcd&quot;</span>);   <span class=\"tok-c\">// -&gt; { status: 'InvalidUserName', errorMessage: 'User name cannot be empty.' }</span>\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">createUser</span>(<span class=\"tok-s\">&quot;x&quot;</span>, <span class=\"tok-s\">&quot;abc&quot;</span>);     <span class=\"tok-c\">// -&gt; { status: 'InvalidPassword', errorMessage: 'Password must be at least 4 characters.' }</span>\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">createUser</span>(<span class=\"tok-s\">&quot;  Eve &quot;</span>, <span class=\"tok-s\">&quot;abcd&quot;</span>, <span class=\"tok-s\">&quot;e@x.com&quot;</span>, <span class=\"tok-s\">&quot;Q&quot;</span>, <span class=\"tok-s\">&quot;A&quot;</span>);\n<span class=\"tok-c\">// -&gt; { status: 'Success', user: { userName: 'Eve', email: 'e@x.com', roles: [ 'User' ], isLockedOut: false, isApproved: true, ... } }</span>\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">createUser</span>(<span class=\"tok-s\">&quot;EVE&quot;</span>, <span class=\"tok-s\">&quot;abcd&quot;</span>);                <span class=\"tok-c\">// -&gt; { status: 'DuplicateUserName', errorMessage: 'A user with that name already exists.' }</span>\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">createUser</span>(<span class=\"tok-s\">&quot;eve2&quot;</span>, <span class=\"tok-s\">&quot;abcd&quot;</span>, <span class=\"tok-s\">&quot;E@X.COM&quot;</span>);    <span class=\"tok-c\">// -&gt; { status: 'DuplicateEmail', errorMessage: 'A user with that email already exists.' }</span>\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">validateUser</span>(<span class=\"tok-s\">&quot;  Eve &quot;</span>, <span class=\"tok-s\">&quot;abcd&quot;</span>);           <span class=\"tok-c\">// -&gt; false  (lookup does not trim, but createUser stored the key trimmed)</span>\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">validateUser</span>(<span class=\"tok-s\">&quot;eve&quot;</span>, <span class=\"tok-s\">&quot;abcd&quot;</span>);              <span class=\"tok-c\">// -&gt; true</span>\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">resetPassword</span>(<span class=\"tok-s\">&quot;eve&quot;</span>);                     <span class=\"tok-c\">// -&gt; null   (answer required because one is stored)</span>\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">resetPassword</span>(<span class=\"tok-s\">&quot;eve&quot;</span>, <span class=\"tok-s\">&quot;a &quot;</span>);               <span class=\"tok-c\">// -&gt; &quot;Temp#d9nkay!&quot; (random)</span></code></pre></div>\n","lock-out-example":"<h3 id=\"45-lock-out-example\">4.5 Lock-out example<a class=\"anchor\" href=\"#45-lock-out-example\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> p = <span class=\"tok-k\">new</span> <span class=\"tok-t\">InMemoryAuthProvider</span>({ maxInvalidPasswordAttempts: <span class=\"tok-n\">3</span>, users: [{ userName: <span class=\"tok-s\">&quot;Bob&quot;</span>, password: <span class=\"tok-s\">&quot;secret&quot;</span>, roles: [<span class=\"tok-s\">&quot;Users&quot;</span>] }] });\n<span class=\"tok-k\">const</span> l = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginController</span>({ provider: p, userName: <span class=\"tok-s\">&quot;bob&quot;</span>, password: <span class=\"tok-s\">&quot;x&quot;</span> });\n<span class=\"tok-k\">for</span> (<span class=\"tok-k\">let</span> i = <span class=\"tok-n\">0</span>; i &lt; <span class=\"tok-n\">3</span>; i++) <span class=\"tok-k\">await</span> l.<span class=\"tok-f\">login</span>();\nconsole.<span class=\"tok-f\">log</span>((<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">getUser</span>(<span class=\"tok-s\">&quot;bob&quot;</span>)).isLockedOut);           <span class=\"tok-c\">// -&gt; true</span>\nl.password = <span class=\"tok-s\">&quot;secret&quot;</span>;\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> l.<span class=\"tok-f\">login</span>(), l.failureMessage);              <span class=\"tok-c\">// -&gt; false Your login attempt was not successful. Please try again.</span>\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">unlockUser</span>(<span class=\"tok-s\">&quot;BOB&quot;</span>), <span class=\"tok-k\">await</span> l.<span class=\"tok-f\">login</span>());     <span class=\"tok-c\">// -&gt; true true</span></code></pre></div>\n<hr>\n"},"securitymanager":{"overview":"<p>Static registry for the active provider and the global change broadcaster. ASP.NET equivalent: <code>Membership.Provider</code> + <code>FormsAuthentication</code>.</p>\n","static-members":"<h3 id=\"51-static-members\">5.1 Static members<a class=\"anchor\" href=\"#51-static-members\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>defaultProvider</code></td><td><code>IMembershipProvider</code></td><td>r (getter)</td><td><code>InMemoryAuthProvider</code> seeded with <code>admin</code> and <code>user</code> (see Quick start)</td><td>Provider used by controllers created <strong>after</strong> this is read.</td></tr><tr><td><code>currentUserChanged</code></td><td><code>EventDispatcher&lt;IMembershipProvider, IUser | null&gt;</code></td><td>r (static readonly)</td><td>n/a</td><td>Raised by <code>setProvider</code> and <code>notifyCurrentUserChanged</code>. Args: the new user or <code>null</code>. Not cancellable.</td></tr></tbody></table></div>\n","methods":"<h3 id=\"52-methods\">5.2 Methods<a class=\"anchor\" href=\"#52-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>static setProvider(provider: IMembershipProvider): void</code></td><td><code>void</code></td><td>no</td><td>Replaces the default provider and raises <code>currentUserChanged(provider, provider.getCurrentUser())</code> (not awaited).</td></tr><tr><td><code>static notifyCurrentUserChanged(user: IUser | null): void</code></td><td><code>void</code></td><td>no</td><td>Raises <code>currentUserChanged(currentDefaultProvider, user)</code> (not awaited). Providers call this on login/logout. The sender is always the <strong>default</strong> provider, even if the notifier is a different instance.</td></tr></tbody></table></div>\n","gotchas":"<h3 id=\"53-gotchas\">5.3 Gotchas<a class=\"anchor\" href=\"#53-gotchas\" aria-label=\"Link to this section\">#</a></h3>\n<ul><li>Controllers read <code>SecurityManager.defaultProvider</code> <strong>once, in their constructor</strong>. Calling <code>setProvider</code> later does not re-point existing controllers; recreate them or pass <code>provider</code> explicitly. Verified: after <code>SecurityManager.setProvider(new InMemoryAuthProvider({ name: &quot;Other&quot; }))</code>, an existing <code>LoginController</code> still reports <code>isLoggedIn === true</code> from the old provider, while a new one reports <code>false</code>.</li><li><code>LoginView</code>, <code>LoginStatus</code>, <code>LoginName</code> subscribe to the <strong>global</strong> dispatcher regardless of which provider they were given, so they refresh on any provider's notification.</li><li>Call <code>dispose()</code> on those three controllers when discarding them; otherwise the static dispatcher keeps them alive.</li></ul>\n<hr>\n"},"logincontroller":{"overview":"<p>Credential form state and the login workflow. ASP.NET equivalent: <code>&lt;asp:Login&gt;</code>.</p>\n","constructor-options-loginoptions":"<h3 id=\"61-constructor-options-loginoptions\">6.1 Constructor options (<code>LoginOptions</code>)<a class=\"anchor\" href=\"#61-constructor-options-loginoptions\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td><code>Login_&lt;random7&gt;</code></td><td>Identifier.</td></tr><tr><td><code>userName</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Initial user name.</td></tr><tr><td><code>password</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Initial password.</td></tr><tr><td><code>rememberMeSet</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Initial &quot;remember me&quot;.</td></tr><tr><td><code>displayRememberMe</code></td><td><code>boolean</code></td><td><code>true</code></td><td>UI hint: show the checkbox.</td></tr><tr><td><code>destinationPageUrl</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Where the adapter should navigate after success. Stored only; the controller never navigates.</td></tr><tr><td><code>failureText</code></td><td><code>string</code></td><td><code>&quot;Your login attempt was not successful. Please try again.&quot;</code></td><td>Message used for any failed login.</td></tr><tr><td><code>helpPageUrl</code> / <code>helpPageText</code></td><td><code>string</code></td><td><code>undefined</code> / <code>&quot;Help&quot;</code></td><td>UI hint link.</td></tr><tr><td><code>passwordRecoveryUrl</code> / <code>passwordRecoveryText</code></td><td><code>string</code></td><td><code>undefined</code> / <code>&quot;Forgot your password?&quot;</code></td><td>UI hint link.</td></tr><tr><td><code>createUserUrl</code> / <code>createUserText</code></td><td><code>string</code></td><td><code>undefined</code> / <code>&quot;Sign Up&quot;</code></td><td>UI hint link.</td></tr><tr><td><code>userNameRequiredErrorMessage</code></td><td><code>string</code></td><td><code>&quot;User Name is required.&quot;</code></td><td>Validation message.</td></tr><tr><td><code>passwordRequiredErrorMessage</code></td><td><code>string</code></td><td><code>&quot;Password is required.&quot;</code></td><td>Validation message.</td></tr><tr><td><code>visibleWhenLoggedIn</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Controls <code>isVisible</code>.</td></tr><tr><td><code>validationGroup</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Stored/returned in state only. Not wired to <code>ValidatorManager</code>.</td></tr><tr><td><code>provider</code></td><td><code>IMembershipProvider</code></td><td><code>SecurityManager.defaultProvider</code> (captured at construction)</td><td>Backend.</td></tr></tbody></table></div>\n","properties":"<h3 id=\"62-properties\">6.2 Properties<a class=\"anchor\" href=\"#62-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>r</td><td>see above</td><td></td></tr><tr><td><code>userName</code></td><td><code>string</code></td><td>rw</td><td><code>&quot;&quot;</code></td><td>Setting directly does not emit <code>stateChanged</code>; use <code>setUserName</code>.</td></tr><tr><td><code>password</code></td><td><code>string</code></td><td>rw</td><td><code>&quot;&quot;</code></td><td>Cleared after successful login.</td></tr><tr><td><code>rememberMeSet</code></td><td><code>boolean</code></td><td>rw</td><td><code>false</code></td><td></td></tr><tr><td><code>displayRememberMe</code></td><td><code>boolean</code></td><td>rw</td><td><code>true</code></td><td></td></tr><tr><td><code>destinationPageUrl</code>, <code>helpPageUrl</code>, <code>passwordRecoveryUrl</code>, <code>createUserUrl</code>, <code>validationGroup</code></td><td><code>string | undefined</code></td><td>rw</td><td><code>undefined</code></td><td></td></tr><tr><td><code>failureText</code>, <code>helpPageText</code>, <code>passwordRecoveryText</code>, <code>createUserText</code>, <code>userNameRequiredErrorMessage</code>, <code>passwordRequiredErrorMessage</code></td><td><code>string</code></td><td>rw</td><td>see options</td><td></td></tr><tr><td><code>visibleWhenLoggedIn</code></td><td><code>boolean</code></td><td>rw</td><td><code>false</code></td><td></td></tr><tr><td><code>failureMessage</code></td><td><code>string | null</code></td><td>r</td><td><code>null</code></td><td>Set on failed login; reset at the start of every <code>login()</code>.</td></tr><tr><td><code>validationErrors</code></td><td><code>string[]</code></td><td>r</td><td><code>[]</code></td><td>Copy of the last <code>validate()</code> result.</td></tr><tr><td><code>currentUser</code></td><td><code>IUser | null</code></td><td>r</td><td>n/a</td><td><code>provider.getCurrentUser()</code>.</td></tr><tr><td><code>isLoggedIn</code> / <code>isAuthenticated</code></td><td><code>boolean</code></td><td>r</td><td>n/a</td><td><code>currentUser !== null</code> (identical).</td></tr><tr><td><code>isVisible</code></td><td><code>boolean</code></td><td>r</td><td>n/a</td><td><code>false</code> only when logged in and <code>visibleWhenLoggedIn</code> is <code>false</code>.</td></tr></tbody></table></div>\n","methods":"<h3 id=\"63-methods\">6.3 Methods<a class=\"anchor\" href=\"#63-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>setUserName(value: string)</code></td><td><code>void</code></td><td>no</td><td>Sets <code>userName</code>, emits <code>stateChanged</code>.</td></tr><tr><td><code>setPassword(value: string)</code></td><td><code>void</code></td><td>no</td><td>Sets <code>password</code>, emits <code>stateChanged</code>.</td></tr><tr><td><code>setRememberMe(value: boolean)</code></td><td><code>void</code></td><td>no</td><td>Sets <code>rememberMeSet</code>, emits <code>stateChanged</code>.</td></tr><tr><td><code>validate()</code></td><td><code>boolean</code></td><td>no</td><td>Rebuilds <code>validationErrors</code> (user name required after trim; password required, not trimmed).</td></tr><tr><td><code>authenticate()</code></td><td><code>Promise&lt;boolean&gt;</code></td><td>provider rejection</td><td><code>provider.validateUser(userName, password)</code>. No events, no session.</td></tr><tr><td><code>login()</code></td><td><code>Promise&lt;boolean&gt;</code></td><td>provider/handler rejection</td><td>The workflow in section 2.2.</td></tr><tr><td><code>getState()</code></td><td><code>LoginState</code></td><td>no</td><td>Snapshot. <strong>Calls <code>validate()</code></strong>, so it overwrites <code>validationErrors</code> as a side effect. After a successful login the password is empty, so <code>isValid</code> is <code>false</code>.</td></tr></tbody></table></div>\n","events":"<h3 id=\"64-events\">6.4 Events<a class=\"anchor\" href=\"#64-events\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>loggingIn</code></td><td><code>LoginCancelEventArgs</code> <code>{ userName, password, rememberMe, cancel }</code></td><td>yes</td><td>After validation passes, before the provider call.</td><td><code>cancel</code> (changing <code>userName</code>/<code>password</code>/<code>rememberMe</code> on the args has <strong>no</strong> effect on the call).</td></tr><tr><td><code>loggedIn</code></td><td><code>LoginEventArgs</code> <code>{ userName: string; user: IUser }</code></td><td>no</td><td>After provider success; <code>password</code> already cleared.</td><td>none</td></tr><tr><td><code>loginError</code></td><td><code>LoginErrorEventArgs</code> <code>{ userName: string; errorMessage: string }</code></td><td>no</td><td>After provider returned <code>false</code>.</td><td>none</td></tr><tr><td><code>stateChanged</code></td><td><code>LoginState</code></td><td>no</td><td>After setters, validation failure, success, failure (not awaited).</td><td>none</td></tr></tbody></table></div>\n<p><code>LoginState</code> fields: <code>userName</code>, <code>rememberMeSet</code>, <code>displayRememberMe</code>, <code>destinationPageUrl?</code>, <code>failureText</code>, <code>helpPageUrl?</code>, <code>helpPageText</code>, <code>passwordRecoveryUrl?</code>, <code>passwordRecoveryText</code>, <code>createUserUrl?</code>, <code>createUserText</code>, <code>visibleWhenLoggedIn</code>, <code>validationGroup?</code>, <code>isAuthenticated</code>, <code>isLoggedIn</code>, <code>failureMessage</code>, <code>currentUser</code>, <code>isValid</code>, <code>validationErrors</code>. (<code>password</code> is deliberately not in the state.)</p>\n","example-validation-cancel":"<h3 id=\"65-example-validation-cancel\">6.5 Example: validation, cancel<a class=\"anchor\" href=\"#65-example-validation-cancel\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> login = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginController</span>();\n<span class=\"tok-k\">let</span> fired = <span class=\"tok-n\">0</span>;\nlogin.loggingIn.<span class=\"tok-f\">subscribe</span>(() =&gt; fired++);\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> login.<span class=\"tok-f\">login</span>(), fired, login.validationErrors, login.failureMessage);\n<span class=\"tok-c\">// -&gt; false 0 [ 'User Name is required.', 'Password is required.' ] null</span></code></pre></div>\n<hr>\n"},"loginviewcontroller":{"overview":"<p>Chooses a template for the current auth state. ASP.NET equivalent: <code>&lt;asp:LoginView&gt;</code>. <code>T</code> is whatever your UI layer uses as a &quot;template&quot; (string, React node factory, Angular <code>TemplateRef</code>, ...); the controller never inspects it.</p>\n","types":"<h3 id=\"71-types\">7.1 Types<a class=\"anchor\" href=\"#71-types\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">interface</span> <span class=\"tok-t\">RoleGroup</span>&lt;<span class=\"tok-t\">T</span> = unknown&gt; { roles: string[]; contentTemplate: <span class=\"tok-t\">T</span> }\n<span class=\"tok-k\">type</span> <span class=\"tok-t\">LoginViewResolvedType</span> = <span class=\"tok-s\">&quot;Anonymous&quot;</span> | <span class=\"tok-s\">&quot;RoleGroup&quot;</span> | <span class=\"tok-s\">&quot;LoggedIn&quot;</span>;\n<span class=\"tok-k\">interface</span> <span class=\"tok-t\">LoginViewResolvedView</span>&lt;<span class=\"tok-t\">T</span> = unknown&gt; {\n  <span class=\"tok-k\">type</span>: <span class=\"tok-t\">LoginViewResolvedType</span>;\n  template?: <span class=\"tok-t\">T</span> | <span class=\"tok-k\">undefined</span>;\n  matchedRole?: string | <span class=\"tok-k\">undefined</span>;          <span class=\"tok-c\">// the role string from the RoleGroup (as written there)</span>\n  matchedRoleGroupIndex?: number | <span class=\"tok-k\">undefined</span>;\n  user: <span class=\"tok-t\">IUser</span> | <span class=\"tok-k\">null</span>;\n}</code></pre></div>\n","constructor-options-loginviewoptions":"<h3 id=\"72-constructor-options-loginviewoptions\">7.2 Constructor options (<code>LoginViewOptions&lt;T&gt;</code>)<a class=\"anchor\" href=\"#72-constructor-options-loginviewoptions\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td><code>LoginView_&lt;random7&gt;</code></td><td></td></tr><tr><td><code>anonymousTemplate</code></td><td><code>T</code></td><td><code>undefined</code></td><td>Template when nobody is logged in.</td></tr><tr><td><code>loggedInTemplate</code></td><td><code>T</code></td><td><code>undefined</code></td><td>Template when logged in and no role group matches.</td></tr><tr><td><code>roleGroups</code></td><td><code>RoleGroup&lt;T&gt;[]</code></td><td><code>[]</code></td><td>Copied (array shallow-copied).</td></tr><tr><td><code>provider</code></td><td><code>IMembershipProvider</code></td><td><code>SecurityManager.defaultProvider</code></td><td>Source of <code>getCurrentUser()</code>.</td></tr></tbody></table></div>\n<p>The constructor subscribes to <code>SecurityManager.currentUserChanged</code>.</p>\n","properties":"<h3 id=\"73-properties\">7.3 Properties<a class=\"anchor\" href=\"#73-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>r</td><td></td><td></td></tr><tr><td><code>anonymousTemplate</code>, <code>loggedInTemplate</code></td><td><code>T | undefined</code></td><td>rw</td><td><code>undefined</code></td><td></td></tr><tr><td><code>roleGroups</code></td><td><code>RoleGroup&lt;T&gt;[]</code></td><td>rw</td><td><code>[]</code></td><td></td></tr><tr><td><code>currentUser</code></td><td><code>IUser | null</code></td><td>r</td><td></td><td><code>provider.getCurrentUser()</code>.</td></tr><tr><td><code>isAuthenticated</code></td><td><code>boolean</code></td><td>r</td><td></td><td><code>currentUser !== null</code>.</td></tr></tbody></table></div>\n","methods":"<h3 id=\"74-methods\">7.4 Methods<a class=\"anchor\" href=\"#74-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>resolveActiveView()</code></td><td><code>LoginViewResolvedView&lt;T&gt;</code></td><td>no</td><td>Section 2.6. Pure read.</td></tr><tr><td><code>notifyViewChanged()</code></td><td><code>void</code></td><td>no</td><td>Resolves the view and raises <code>viewChanged</code> (not awaited). Called automatically on <code>currentUserChanged</code>.</td></tr><tr><td><code>dispose()</code></td><td><code>void</code></td><td>no</td><td>Unsubscribes from the global dispatcher. Idempotent.</td></tr></tbody></table></div>\n","events":"<h3 id=\"75-events\">7.5 Events<a class=\"anchor\" href=\"#75-events\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>viewChanged</code></td><td><code>LoginViewResolvedView&lt;T&gt;</code></td><td>no</td><td>Every global <code>currentUserChanged</code> (even if the resolved view is identical) and on <code>notifyViewChanged()</code>.</td><td>none</td></tr></tbody></table></div>\n","example":"<h3 id=\"76-example\">7.6 Example<a class=\"anchor\" href=\"#76-example\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> lv = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginViewController</span>({\n  anonymousTemplate: <span class=\"tok-s\">&quot;Please sign in&quot;</span>, loggedInTemplate: <span class=\"tok-s\">&quot;Hello user&quot;</span>,\n  roleGroups: [\n    { roles: [<span class=\"tok-s\">&quot;Administrators&quot;</span>], contentTemplate: <span class=\"tok-s\">&quot;Admin panel&quot;</span> },\n    { roles: [<span class=\"tok-s\">&quot;Users&quot;</span>, <span class=\"tok-s\">&quot;Managers&quot;</span>], contentTemplate: <span class=\"tok-s\">&quot;Member area&quot;</span> },\n  ],\n});\nlv.viewChanged.<span class=\"tok-f\">subscribe</span>((s, v) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;viewChanged&quot;</span>, v.<span class=\"tok-k\">type</span>, v.template, v.matchedRole, v.matchedRoleGroupIndex, v.user?.userName ?? <span class=\"tok-k\">null</span>));\nconsole.<span class=\"tok-f\">log</span>(lv.<span class=\"tok-f\">resolveActiveView</span>());          <span class=\"tok-c\">// -&gt; { type: 'Anonymous', template: 'Please sign in', user: null }</span>\n<span class=\"tok-k\">const</span> p = <span class=\"tok-t\">SecurityManager</span>.defaultProvider;\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">login</span>(<span class=\"tok-s\">&quot;user&quot;</span>, <span class=\"tok-s\">&quot;Password123!&quot;</span>);        <span class=\"tok-c\">// -&gt; viewChanged RoleGroup Member area Users 1 user</span>\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">logout</span>();                             <span class=\"tok-c\">// -&gt; viewChanged Anonymous Please sign in undefined undefined null</span>\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">login</span>(<span class=\"tok-s\">&quot;admin&quot;</span>, <span class=\"tok-s\">&quot;Password123!&quot;</span>);       <span class=\"tok-c\">// -&gt; viewChanged RoleGroup Admin panel Administrators 0 admin</span>\n<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">logout</span>();\nlv.<span class=\"tok-f\">dispose</span>();                                 <span class=\"tok-c\">// later logins raise no more events</span></code></pre></div>\n<p>(<code>admin</code> has both <code>Administrators</code> and <code>Users</code>; group 0 is listed first so it wins.)</p>\n<hr>\n"},"loginstatuscontroller-and-loginnamecontroller":{"loginstatuscontroller":"<h3 id=\"81-loginstatuscontroller\">8.1 <code>LoginStatusController</code><a class=\"anchor\" href=\"#81-loginstatuscontroller\" aria-label=\"Link to this section\">#</a></h3>\n<p>Login/Logout toggle. ASP.NET equivalent: <code>&lt;asp:LoginStatus&gt;</code>.</p>\n<p><code>type LogoutAction = &quot;Refresh&quot; | &quot;Redirect&quot;</code>.</p>\n<p><strong>Constructor options (<code>LoginStatusOptions</code>)</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td><code>LoginStatus_&lt;random7&gt;</code></td><td></td></tr><tr><td><code>loginText</code></td><td><code>string</code></td><td><code>&quot;Login&quot;</code></td><td>Text when logged out.</td></tr><tr><td><code>logoutText</code></td><td><code>string</code></td><td><code>&quot;Logout&quot;</code></td><td>Text when logged in.</td></tr><tr><td><code>loginPageUrl</code></td><td><code>string</code></td><td><code>undefined</code></td><td><code>targetUrl</code> when logged out.</td></tr><tr><td><code>logoutPageUrl</code></td><td><code>string</code></td><td><code>undefined</code></td><td><code>targetUrl</code> when logged in.</td></tr><tr><td><code>logoutAction</code></td><td><code>LogoutAction</code></td><td><code>&quot;Refresh&quot;</code></td><td>Hint for the adapter; the controller never navigates or reloads.</td></tr><tr><td><code>provider</code></td><td><code>IMembershipProvider</code></td><td><code>SecurityManager.defaultProvider</code></td><td></td></tr></tbody></table></div>\n<p><strong>Properties</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>r</td><td></td><td></td></tr><tr><td><code>loginText</code>, <code>logoutText</code></td><td><code>string</code></td><td>rw</td><td>see above</td><td></td></tr><tr><td><code>loginPageUrl</code>, <code>logoutPageUrl</code></td><td><code>string | undefined</code></td><td>rw</td><td><code>undefined</code></td><td></td></tr><tr><td><code>logoutAction</code></td><td><code>LogoutAction</code></td><td>rw</td><td><code>&quot;Refresh&quot;</code></td><td></td></tr><tr><td><code>currentUser</code></td><td><code>IUser | null</code></td><td>r</td><td></td><td></td></tr><tr><td><code>isLoggedIn</code></td><td><code>boolean</code></td><td>r</td><td></td><td></td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>r</td><td></td><td><code>logoutText</code> if logged in else <code>loginText</code>.</td></tr><tr><td><code>targetUrl</code></td><td><code>string | undefined</code></td><td>r</td><td></td><td><code>logoutPageUrl</code> if logged in else <code>loginPageUrl</code>.</td></tr></tbody></table></div>\n<p><strong>Methods</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>logout()</code></td><td><code>Promise&lt;boolean&gt;</code></td><td>provider/handler rejection</td><td>If not logged in -&gt; <code>false</code> immediately (no events). Else raises <code>loggingOut</code>; cancelled -&gt; <code>false</code>. Otherwise <code>await provider.logout()</code>, raises <code>loggedOut</code>, emits state, <code>true</code>.</td></tr><tr><td><code>executeAction()</code></td><td><code>Promise&lt;boolean&gt;</code></td><td>as above</td><td>Logged in -&gt; <code>logout()</code>. Logged out -&gt; returns <code>true</code> and does nothing (the adapter is expected to navigate to <code>loginPageUrl</code>).</td></tr><tr><td><code>getState()</code></td><td><code>LoginStatusState</code></td><td>no</td><td><code>{ isLoggedIn, text, targetUrl?, logoutAction, currentUser }</code>.</td></tr><tr><td><code>dispose()</code></td><td><code>void</code></td><td>no</td><td>Unsubscribes from <code>SecurityManager.currentUserChanged</code>.</td></tr></tbody></table></div>\n<p><strong>Events</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>loggingOut</code></td><td><code>CancelEventArgs</code></td><td>yes</td><td>Before <code>provider.logout()</code>.</td><td><code>cancel</code></td></tr><tr><td><code>loggedOut</code></td><td><code>void</code> (<code>undefined</code>)</td><td>no</td><td>After <code>provider.logout()</code>.</td><td>none</td></tr><tr><td><code>stateChanged</code></td><td><code>LoginStatusState</code></td><td>no</td><td>On every global <code>currentUserChanged</code> and after <code>logout()</code>. Because <code>InMemoryAuthProvider.logout()</code> itself notifies, a successful logout emits it <strong>twice</strong>.</td><td>none</td></tr></tbody></table></div>\n","loginnamecontroller":"<h3 id=\"82-loginnamecontroller\">8.2 <code>LoginNameController</code><a class=\"anchor\" href=\"#82-loginnamecontroller\" aria-label=\"Link to this section\">#</a></h3>\n<p>Greeting text. ASP.NET equivalent: <code>&lt;asp:LoginName&gt;</code>.</p>\n<p><strong>Constructor options (<code>LoginNameOptions</code>)</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td><code>LoginName_&lt;random7&gt;</code></td><td></td></tr><tr><td><code>formatString</code></td><td><code>string</code></td><td><code>&quot;Welcome, {0}&quot;</code></td><td>Every <code>{0}</code> is replaced by the user name (global replace).</td></tr><tr><td><code>provider</code></td><td><code>IMembershipProvider</code></td><td><code>SecurityManager.defaultProvider</code></td><td></td></tr></tbody></table></div>\n<p><strong>Properties</strong>: <code>id</code> (r), <code>formatString</code> (rw), <code>currentUser</code> (r), <code>isLoggedIn</code> (r), <code>userName</code> (r, <code>&quot;&quot;</code> when logged out), <code>formattedText</code> (r, <code>&quot;&quot;</code> when logged out).</p>\n<p><strong>Methods</strong>: <code>getState(): LoginNameState</code> (<code>{ userName, formattedText, isLoggedIn, currentUser }</code>), <code>dispose(): void</code>.</p>\n<p><strong>Events</strong>: <code>stateChanged</code> (<code>LoginNameState</code>, not cancellable, raised on every global <code>currentUserChanged</code>).</p>\n<blockquote class=\"\"><p><code>formattedText</code> does not HTML-escape the user name. Escape in your renderer (React/Angular do this for you).</p></blockquote>\n","example":"<h3 id=\"83-example\">8.3 Example<a class=\"anchor\" href=\"#83-example\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> ls = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginStatusController</span>({ loginPageUrl: <span class=\"tok-s\">&quot;/login&quot;</span>, logoutPageUrl: <span class=\"tok-s\">&quot;/bye&quot;</span> });\n<span class=\"tok-k\">const</span> ln = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginNameController</span>({ formatString: <span class=\"tok-s\">&quot;Hi {0}! ({0})&quot;</span> });\nls.stateChanged.<span class=\"tok-f\">subscribe</span>((s, st) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;status&quot;</span>, st.isLoggedIn, st.text, st.targetUrl));\nls.loggingOut.<span class=\"tok-f\">subscribe</span>(() =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;loggingOut&quot;</span>));\nls.loggedOut.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;loggedOut&quot;</span>, e));\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-t\">JSON</span>.<span class=\"tok-f\">stringify</span>(ln.formattedText), <span class=\"tok-k\">await</span> ls.<span class=\"tok-f\">logout</span>(), <span class=\"tok-k\">await</span> ls.<span class=\"tok-f\">executeAction</span>());\n<span class=\"tok-c\">// -&gt; &quot;&quot; false true</span>\n<span class=\"tok-k\">await</span> <span class=\"tok-t\">SecurityManager</span>.defaultProvider.<span class=\"tok-f\">login</span>(<span class=\"tok-s\">&quot;user&quot;</span>, <span class=\"tok-s\">&quot;Password123!&quot;</span>);\n<span class=\"tok-c\">// -&gt; status true Logout /bye</span>\nconsole.<span class=\"tok-f\">log</span>(ln.formattedText);                <span class=\"tok-c\">// -&gt; Hi user! (user)</span>\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> ls.<span class=\"tok-f\">executeAction</span>());\n<span class=\"tok-c\">// -&gt; loggingOut / status false Login /login / loggedOut undefined / status false Login /login / true</span></code></pre></div>\n<hr>\n"},"changepasswordcontroller":{"overview":"<p>Password-change form. ASP.NET equivalent: <code>&lt;asp:ChangePassword&gt;</code>.</p>\n<p><code>type ChangePasswordViewType = &quot;ChangePassword&quot; | &quot;Success&quot;</code>.</p>\n","constructor-options-changepasswordoptions":"<h3 id=\"91-constructor-options-changepasswordoptions\">9.1 Constructor options (<code>ChangePasswordOptions</code>)<a class=\"anchor\" href=\"#91-constructor-options-changepasswordoptions\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td><code>ChangePassword_&lt;random7&gt;</code></td><td></td></tr><tr><td><code>userName</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Target user. If blank, the provider's current user is used.</td></tr><tr><td><code>currentPassword</code>, <code>newPassword</code>, <code>confirmNewPassword</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Initial field values.</td></tr><tr><td><code>successText</code></td><td><code>string</code></td><td><code>&quot;Your password has been changed.&quot;</code></td><td>Text for the success view.</td></tr><tr><td><code>continueDestinationPageUrl</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint.</td></tr><tr><td><code>newPasswordRegularExpression</code></td><td><code>RegExp | string</code></td><td><code>undefined</code></td><td>Extra complexity rule. Strings are compiled with <code>new RegExp(str)</code> on every <code>validate()</code> (an invalid pattern throws <code>SyntaxError</code> from <code>validate()</code>).</td></tr><tr><td><code>newPasswordRegularExpressionErrorMessage</code></td><td><code>string</code></td><td><code>&quot;Password does not meet complexity requirements.&quot;</code></td><td></td></tr><tr><td><code>confirmPasswordCompareErrorMessage</code></td><td><code>string</code></td><td><code>&quot;The Confirm New Password must match the New Password entry.&quot;</code></td><td></td></tr><tr><td><code>changePasswordFailureText</code></td><td><code>string</code></td><td><code>&quot;Password change failed. Please re-enter your values and try again.&quot;</code></td><td></td></tr><tr><td><code>provider</code></td><td><code>IMembershipProvider</code></td><td><code>SecurityManager.defaultProvider</code></td><td></td></tr></tbody></table></div>\n","properties":"<h3 id=\"92-properties\">9.2 Properties<a class=\"anchor\" href=\"#92-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>r</td><td></td><td></td></tr><tr><td><code>userName</code></td><td><code>string | undefined</code></td><td>rw</td><td><code>undefined</code></td><td></td></tr><tr><td><code>currentPassword</code>, <code>newPassword</code>, <code>confirmNewPassword</code></td><td><code>string</code></td><td>rw</td><td><code>&quot;&quot;</code></td><td></td></tr><tr><td><code>successText</code></td><td><code>string</code></td><td>rw</td><td>see above</td><td></td></tr><tr><td><code>continueDestinationPageUrl</code></td><td><code>string | undefined</code></td><td>rw</td><td></td><td></td></tr><tr><td><code>newPasswordRegularExpression</code></td><td><code>RegExp | string | undefined</code></td><td>rw</td><td></td><td></td></tr><tr><td><code>newPasswordRegularExpressionErrorMessage</code>, <code>confirmPasswordCompareErrorMessage</code>, <code>changePasswordFailureText</code></td><td><code>string</code></td><td>rw</td><td></td><td></td></tr><tr><td><code>activeView</code></td><td><code>ChangePasswordViewType</code></td><td>r</td><td><code>&quot;ChangePassword&quot;</code></td><td><code>&quot;Success&quot;</code> after a successful change.</td></tr><tr><td><code>isSuccess</code></td><td><code>boolean</code></td><td>r</td><td><code>false</code></td><td><code>activeView === &quot;Success&quot;</code>.</td></tr><tr><td><code>failureMessage</code></td><td><code>string | null</code></td><td>r</td><td><code>null</code></td><td></td></tr><tr><td><code>validationErrors</code></td><td><code>string[]</code></td><td>r</td><td><code>[]</code></td><td></td></tr><tr><td><code>effectiveUserName</code></td><td><code>string</code></td><td>r</td><td></td><td>Trimmed <code>userName</code> if non-blank; else <code>provider.getCurrentUser()?.userName</code>; else <code>&quot;&quot;</code>.</td></tr></tbody></table></div>\n","methods":"<h3 id=\"93-methods\">9.3 Methods<a class=\"anchor\" href=\"#93-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>setCurrentPassword(v)</code> / <code>setNewPassword(v)</code> / <code>setConfirmNewPassword(v)</code></td><td><code>void</code></td><td>no</td><td>Set field and emit <code>stateChanged</code>.</td></tr><tr><td><code>validate()</code></td><td><code>boolean</code></td><td><code>SyntaxError</code> for invalid regex string</td><td>Rules in order: user name required (<code>&quot;User Name is required.&quot;</code>); current password required (<code>&quot;Current Password is required.&quot;</code>); new password required (<code>&quot;New Password is required.&quot;</code>) else min 4 chars (<code>&quot;New Password must be at least 4 characters.&quot;</code>, hard-coded); regex (only if a new password is present); confirm must equal new (<code>confirmPasswordCompareErrorMessage</code>). Messages other than the regex/compare ones are not configurable.</td></tr><tr><td><code>changePassword()</code></td><td><code>Promise&lt;boolean&gt;</code></td><td>provider/handler rejection</td><td>Clears <code>failureMessage</code>; <code>validate()</code> (fail -&gt; <code>false</code>, no event); raises <code>changingPassword</code> (cancel -&gt; <code>false</code>); <code>provider.changePassword(effectiveUserName, current, new)</code>. Success: <code>activeView = &quot;Success&quot;</code>, all three password fields cleared, <code>changedPassword</code> raised, <code>true</code>. Failure: <code>failureMessage = changePasswordFailureText</code>, <code>changePasswordError</code> raised, <code>false</code>.</td></tr><tr><td><code>continue()</code></td><td><code>void</code></td><td>no</td><td>Raises <code>continueButtonClick</code> (not awaited). Does not change state.</td></tr><tr><td><code>reset()</code></td><td><code>void</code></td><td>no</td><td>Back to <code>&quot;ChangePassword&quot;</code>, clears messages and password fields (not <code>userName</code>).</td></tr><tr><td><code>getState()</code></td><td><code>ChangePasswordState</code></td><td>as <code>validate()</code></td><td><code>{ activeView, userName: effectiveUserName, successText, continueDestinationPageUrl?, failureMessage, validationErrors, isValid, isSuccess }</code>. Calls <code>validate()</code> (overwrites <code>validationErrors</code>).</td></tr></tbody></table></div>\n","events":"<h3 id=\"94-events\">9.4 Events<a class=\"anchor\" href=\"#94-events\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>changingPassword</code></td><td><code>ChangePasswordCancelEventArgs</code> <code>{ userName, currentPassword, newPassword, cancel }</code></td><td>yes</td><td>After validation, before the provider call.</td><td><code>cancel</code> only</td></tr><tr><td><code>changedPassword</code></td><td><code>void</code></td><td>no</td><td>After success.</td><td>none</td></tr><tr><td><code>changePasswordError</code></td><td><code>string</code> (failure text)</td><td>no</td><td>After the provider returned <code>false</code>.</td><td>none</td></tr><tr><td><code>continueButtonClick</code></td><td><code>void</code></td><td>no</td><td><code>continue()</code>.</td><td>none</td></tr><tr><td><code>stateChanged</code></td><td><code>ChangePasswordState</code></td><td>no</td><td>Setters, validation failure, success, failure, <code>reset()</code>.</td><td>none</td></tr></tbody></table></div>\n","gotchas":"<h3 id=\"95-gotchas\">9.5 Gotchas<a class=\"anchor\" href=\"#95-gotchas\" aria-label=\"Link to this section\">#</a></h3>\n<ul><li>There is no authorization check: whoever sets <code>userName</code> chooses whose password is changed; the provider's old-password check is the only guard.</li><li>The controller cannot tell why the provider returned <code>false</code> (wrong old password vs policy), so the message is always <code>changePasswordFailureText</code>.</li></ul>\n","example":"<h3 id=\"96-example\">9.6 Example<a class=\"anchor\" href=\"#96-example\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> p = <span class=\"tok-k\">new</span> <span class=\"tok-t\">InMemoryAuthProvider</span>({ users: [{ userName: <span class=\"tok-s\">&quot;alice&quot;</span>, password: <span class=\"tok-s\">&quot;oldpw&quot;</span>, email: <span class=\"tok-s\">&quot;alice@x.com&quot;</span>, roles: [<span class=\"tok-s\">&quot;Users&quot;</span>] }] });\n<span class=\"tok-k\">const</span> cp = <span class=\"tok-k\">new</span> <span class=\"tok-t\">ChangePasswordController</span>({ provider: p, userName: <span class=\"tok-s\">&quot;alice&quot;</span>, newPasswordRegularExpression: <span class=\"tok-s\">&quot;^(?=.*\\\\d).{6,}$&quot;</span> });\ncp.changingPassword.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;changing&quot;</span>, e.userName, e.currentPassword, e.newPassword));\ncp.changedPassword.<span class=\"tok-f\">subscribe</span>(() =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;changed&quot;</span>));\ncp.changePasswordError.<span class=\"tok-f\">subscribe</span>((s, m) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;error:&quot;</span>, m));\n\ncp.currentPassword = <span class=\"tok-s\">&quot;oldpw&quot;</span>; cp.newPassword = <span class=\"tok-s\">&quot;abc&quot;</span>; cp.confirmNewPassword = <span class=\"tok-s\">&quot;abd&quot;</span>;\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> cp.<span class=\"tok-f\">changePassword</span>(), cp.validationErrors);\n<span class=\"tok-c\">// -&gt; false [ 'New Password must be at least 4 characters.',</span>\n<span class=\"tok-c\">//            'Password does not meet complexity requirements.',</span>\n<span class=\"tok-c\">//            'The Confirm New Password must match the New Password entry.' ]</span>\n\ncp.newPassword = cp.confirmNewPassword = <span class=\"tok-s\">&quot;abcdef1&quot;</span>; cp.currentPassword = <span class=\"tok-s\">&quot;nope&quot;</span>;\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> cp.<span class=\"tok-f\">changePassword</span>(), cp.activeView);\n<span class=\"tok-c\">// -&gt; changing alice nope abcdef1 / error: Password change failed. ... / false ChangePassword</span>\n\ncp.currentPassword = <span class=\"tok-s\">&quot;oldpw&quot;</span>;\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> cp.<span class=\"tok-f\">changePassword</span>(), cp.activeView, cp.isSuccess);\n<span class=\"tok-c\">// -&gt; changing alice oldpw abcdef1 / changed / true Success true</span>\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">validateUser</span>(<span class=\"tok-s\">&quot;alice&quot;</span>, <span class=\"tok-s\">&quot;abcdef1&quot;</span>));   <span class=\"tok-c\">// -&gt; true</span></code></pre></div>\n<hr>\n"},"passwordrecoverycontroller-and-createuserwizardcontroller":{"passwordrecoverycontroller":"<h3 id=\"101-passwordrecoverycontroller\">10.1 <code>PasswordRecoveryController</code><a class=\"anchor\" href=\"#101-passwordrecoverycontroller\" aria-label=\"Link to this section\">#</a></h3>\n<p>Multi-step recovery. ASP.NET equivalent: <code>&lt;asp:PasswordRecovery&gt;</code>.</p>\n<p><code>type PasswordRecoveryStep = &quot;UserName&quot; | &quot;Question&quot; | &quot;Success&quot;</code>.</p>\n<p><strong>Constructor options (<code>PasswordRecoveryOptions</code>)</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td><code>PasswordRecovery_&lt;random7&gt;</code></td><td></td></tr><tr><td><code>userName</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td></td></tr><tr><td><code>userNameFailureText</code></td><td><code>string</code></td><td><code>&quot;We were unable to access your information. Please try again.&quot;</code></td><td>Unknown or locked user.</td></tr><tr><td><code>questionFailureText</code></td><td><code>string</code></td><td><code>&quot;Your answer could not be verified. Please try again.&quot;</code></td><td><code>resetPassword</code> returned null/empty.</td></tr><tr><td><code>successText</code></td><td><code>string</code></td><td><code>&quot;Your password has been sent to you.&quot;</code></td><td>Display text only.</td></tr><tr><td><code>requireQuestionAndAnswer</code></td><td><code>boolean</code></td><td><code>true</code></td><td><code>false</code> skips the Question step.</td></tr><tr><td><code>provider</code></td><td><code>IMembershipProvider</code></td><td><code>SecurityManager.defaultProvider</code></td><td></td></tr></tbody></table></div>\n<p><strong>Properties</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>r</td><td></td><td></td></tr><tr><td><code>userName</code>, <code>answer</code></td><td><code>string</code></td><td>rw</td><td><code>&quot;&quot;</code></td><td></td></tr><tr><td><code>question</code></td><td><code>string | null</code></td><td>rw</td><td><code>null</code></td><td>Filled when entering the Question step.</td></tr><tr><td><code>userNameFailureText</code>, <code>questionFailureText</code>, <code>successText</code></td><td><code>string</code></td><td>rw</td><td></td><td></td></tr><tr><td><code>requireQuestionAndAnswer</code></td><td><code>boolean</code></td><td>rw</td><td><code>true</code></td><td></td></tr><tr><td><code>currentStep</code></td><td><code>PasswordRecoveryStep</code></td><td>r</td><td><code>&quot;UserName&quot;</code></td><td></td></tr><tr><td><code>failureMessage</code></td><td><code>string | null</code></td><td>r</td><td><code>null</code></td><td></td></tr><tr><td><code>isComplete</code></td><td><code>boolean</code></td><td>r</td><td><code>false</code></td><td><code>currentStep === &quot;Success&quot;</code>.</td></tr></tbody></table></div>\n<p><strong>Methods</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>setUserName(v: string)</code> / <code>setAnswer(v: string)</code></td><td><code>void</code></td><td>no</td><td>Set and emit <code>stateChanged</code>.</td></tr><tr><td><code>submitUserName()</code></td><td><code>Promise&lt;boolean&gt;</code></td><td>provider/handler rejection</td><td>Blank name -&gt; <code>failureMessage = &quot;User Name is required.&quot;</code>, <code>false</code> (no events). Raises <code>verifyingUser</code> (cancel -&gt; <code>false</code>). <code>provider.getUser</code>: unknown or <code>isLockedOut</code> -&gt; <code>userNameFailureText</code>, <code>userLookupError</code> raised, <code>false</code>. If <code>requireQuestionAndAnswer</code>: <code>question = provider.getPasswordQuestion()</code>, step <code>&quot;Question&quot;</code>, <code>true</code>. Else completes recovery directly (below).</td></tr><tr><td><code>submitAnswer()</code></td><td><code>Promise&lt;boolean&gt;</code></td><td>as above</td><td>Blank answer -&gt; <code>failureMessage = &quot;Answer is required.&quot;</code>, <code>false</code>. Raises <code>verifyingAnswer</code> (cancel -&gt; <code>false</code>), then completes recovery with the answer. Can be called in any step (it does not check <code>currentStep</code>).</td></tr><tr><td><code>reset()</code></td><td><code>void</code></td><td>no</td><td>Step <code>&quot;UserName&quot;</code>, clears answer/question/failure (not <code>userName</code>).</td></tr><tr><td><code>getState()</code></td><td><code>PasswordRecoveryState</code></td><td>no</td><td><code>{ currentStep, userName, question, answer, failureMessage, successText, isComplete }</code>.</td></tr></tbody></table></div>\n<p><em>Complete recovery (private):</em> <code>provider.resetPassword(userName, answer)</code>; null/empty -&gt; <code>failureMessage = questionFailureText</code>, <code>answerLookupError</code> raised, <code>false</code>. Otherwise <code>provider.getUser</code> for the email, raise <code>sendingMail</code> with <code>{ userName, recipientEmail, newPassword, cancel }</code>; if cancelled -&gt; <code>false</code> (step unchanged); else step <code>&quot;Success&quot;</code>, <code>true</code>.</p>\n<p><strong>Events</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>verifyingUser</code></td><td><code>CancelEventArgs</code></td><td>yes</td><td>Before looking up the user.</td><td><code>cancel</code></td></tr><tr><td><code>verifyingAnswer</code></td><td><code>CancelEventArgs</code></td><td>yes</td><td>Before resetting with the answer.</td><td><code>cancel</code></td></tr><tr><td><code>sendingMail</code></td><td><code>PasswordRecoveryMailEventArgs</code> <code>{ userName, recipientEmail?, newPassword?, cancel }</code></td><td>yes</td><td>After the provider reset the password.</td><td><code>cancel</code></td></tr><tr><td><code>userLookupError</code></td><td><code>string</code></td><td>no</td><td>Unknown/locked user.</td><td>none</td></tr><tr><td><code>answerLookupError</code></td><td><code>string</code></td><td>no</td><td><code>resetPassword</code> returned no password.</td><td>none</td></tr><tr><td><code>stateChanged</code></td><td><code>PasswordRecoveryState</code></td><td>no</td><td>Setters, step changes, failures, <code>reset()</code>.</td><td>none</td></tr></tbody></table></div>\n<p><strong>Gotchas</strong></p>\n<ul><li><strong>The controller never sends mail.</strong> <code>sendingMail</code> is your hook: read <code>e.newPassword</code> / <code>e.recipientEmail</code> and deliver it. The temporary password is in plain text in the event args.</li><li><strong>Cancelling <code>sendingMail</code> does not undo the reset.</strong> The provider has already changed the password. Verified: after cancelling, the old password no longer validates. A real backend should send the mail itself and make the reset token-based.</li><li>The default provider (<code>InMemoryAuthProvider</code>) allows reset without any answer if the user has no stored answer.</li><li>A wrong answer leaves the controller on the Question step so the user can retry; there is no attempt limit in the controller.</li></ul>\n<p><strong>Example</strong></p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> p = <span class=\"tok-k\">new</span> <span class=\"tok-t\">InMemoryAuthProvider</span>({ users: [{ userName: <span class=\"tok-s\">&quot;alice&quot;</span>, password: <span class=\"tok-s\">&quot;oldpw&quot;</span>, email: <span class=\"tok-s\">&quot;alice@x.com&quot;</span>, roles: [<span class=\"tok-s\">&quot;Users&quot;</span>], passwordQuestion: <span class=\"tok-s\">&quot;Pet?&quot;</span>, passwordAnswer: <span class=\"tok-s\">&quot;Fluffy&quot;</span> }] });\n<span class=\"tok-k\">const</span> pr = <span class=\"tok-k\">new</span> <span class=\"tok-t\">PasswordRecoveryController</span>({ provider: p });\npr.sendingMail.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;sendingMail&quot;</span>, e.userName, e.recipientEmail, /^<span class=\"tok-t\">Temp</span>#.+!$/.<span class=\"tok-f\">test</span>(e.newPassword)));\npr.userLookupError.<span class=\"tok-f\">subscribe</span>((s, m) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;userLookupError&quot;</span>, m));\npr.answerLookupError.<span class=\"tok-f\">subscribe</span>((s, m) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;answerLookupError&quot;</span>, m));\n\npr.userName = <span class=\"tok-s\">&quot;ghost&quot;</span>; console.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> pr.<span class=\"tok-f\">submitUserName</span>(), pr.currentStep);\n<span class=\"tok-c\">// -&gt; userLookupError We were unable to access your information. Please try again. / false UserName</span>\npr.userName = <span class=\"tok-s\">&quot;alice&quot;</span>; console.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> pr.<span class=\"tok-f\">submitUserName</span>(), pr.currentStep, pr.question);\n<span class=\"tok-c\">// -&gt; true Question Pet?</span>\npr.answer = <span class=\"tok-s\">&quot;wrong&quot;</span>; console.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> pr.<span class=\"tok-f\">submitAnswer</span>(), pr.currentStep);\n<span class=\"tok-c\">// -&gt; answerLookupError Your answer could not be verified. Please try again. / false Question</span>\npr.answer = <span class=\"tok-s\">&quot; fluffy &quot;</span>; console.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> pr.<span class=\"tok-f\">submitAnswer</span>(), pr.currentStep, pr.isComplete);\n<span class=\"tok-c\">// -&gt; sendingMail alice alice@x.com true / true Success true</span></code></pre></div>\n","createuserwizardcontroller":"<h3 id=\"102-createuserwizardcontroller\">10.2 <code>CreateUserWizardController</code><a class=\"anchor\" href=\"#102-createuserwizardcontroller\" aria-label=\"Link to this section\">#</a></h3>\n<p>Registration wizard. ASP.NET equivalent: <code>&lt;asp:CreateUserWizard&gt;</code>.</p>\n<p><code>type CreateUserWizardStep = &quot;CreateUser&quot; | &quot;Complete&quot;</code>.</p>\n<p><strong>Constructor options (<code>CreateUserWizardOptions</code>)</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td><code>CreateUserWizard_&lt;random7&gt;</code></td><td></td></tr><tr><td><code>userName</code>, <code>password</code>, <code>confirmPassword</code>, <code>email</code>, <code>question</code>, <code>answer</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Initial field values.</td></tr><tr><td><code>requireEmail</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Email required and must contain <code>@</code>.</td></tr><tr><td><code>disableCreatedUser</code></td><td><code>boolean</code></td><td><code>false</code></td><td>When <code>true</code>, <code>isApproved = false</code> is passed to the provider.</td></tr><tr><td><code>continueDestinationPageUrl</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint.</td></tr><tr><td><code>duplicateUserNameErrorMessage</code></td><td><code>string</code></td><td><code>&quot;Please enter a different user name.&quot;</code></td><td>For <code>DuplicateUserName</code>.</td></tr><tr><td><code>duplicateEmailErrorMessage</code></td><td><code>string</code></td><td><code>&quot;A user name already exists to authorize this e-mail address. Please enter a different e-mail address.&quot;</code></td><td>For <code>DuplicateEmail</code>.</td></tr><tr><td><code>invalidPasswordErrorMessage</code></td><td><code>string</code></td><td><code>&quot;Password length minimum: 4 characters.&quot;</code></td><td>Client-side short password and provider <code>InvalidPassword</code>.</td></tr><tr><td><code>confirmPasswordCompareErrorMessage</code></td><td><code>string</code></td><td><code>&quot;The Confirm Password must match the Password entry.&quot;</code></td><td></td></tr><tr><td><code>provider</code></td><td><code>IMembershipProvider</code></td><td><code>SecurityManager.defaultProvider</code></td><td></td></tr></tbody></table></div>\n<p><strong>Properties</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>r</td><td></td><td></td></tr><tr><td><code>userName</code>, <code>password</code>, <code>confirmPassword</code>, <code>email</code>, <code>question</code>, <code>answer</code></td><td><code>string</code></td><td>rw</td><td><code>&quot;&quot;</code></td><td></td></tr><tr><td><code>requireEmail</code></td><td><code>boolean</code></td><td>rw</td><td><code>true</code></td><td></td></tr><tr><td><code>disableCreatedUser</code></td><td><code>boolean</code></td><td>rw</td><td><code>false</code></td><td></td></tr><tr><td><code>continueDestinationPageUrl</code></td><td><code>string | undefined</code></td><td>rw</td><td></td><td></td></tr><tr><td><code>duplicateUserNameErrorMessage</code>, <code>duplicateEmailErrorMessage</code>, <code>invalidPasswordErrorMessage</code>, <code>confirmPasswordCompareErrorMessage</code></td><td><code>string</code></td><td>rw</td><td></td><td></td></tr><tr><td><code>activeStep</code></td><td><code>CreateUserWizardStep</code></td><td>r</td><td><code>&quot;CreateUser&quot;</code></td><td></td></tr><tr><td><code>isComplete</code></td><td><code>boolean</code></td><td>r</td><td><code>false</code></td><td></td></tr><tr><td><code>user</code></td><td><code>IUser | null</code></td><td>r</td><td><code>null</code></td><td>The created user after success.</td></tr><tr><td><code>failureMessage</code></td><td><code>string | null</code></td><td>r</td><td><code>null</code></td><td></td></tr><tr><td><code>validationErrors</code></td><td><code>string[]</code></td><td>r</td><td><code>[]</code></td><td></td></tr></tbody></table></div>\n<p><strong>Methods</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>setUserName(v)</code>, <code>setPassword(v)</code>, <code>setConfirmPassword(v)</code>, <code>setEmail(v)</code>, <code>setQuestion(v)</code>, <code>setAnswer(v)</code></td><td><code>void</code></td><td>no</td><td>Set and emit <code>stateChanged</code>.</td></tr><tr><td><code>validate()</code></td><td><code>boolean</code></td><td>no</td><td>Rules in order: user name required (<code>&quot;User Name is required.&quot;</code>); password required (<code>&quot;Password is required.&quot;</code>) else min 4 (<code>invalidPasswordErrorMessage</code>); confirm equal (<code>confirmPasswordCompareErrorMessage</code>); if <code>requireEmail</code>: required (<code>&quot;E-mail is required.&quot;</code>) and must include <code>@</code> (<code>&quot;E-mail must be valid.&quot;</code>).</td></tr><tr><td><code>createUser()</code></td><td><code>Promise&lt;boolean&gt;</code></td><td>provider/handler rejection</td><td><code>validate()</code> (fail -&gt; <code>false</code>, no event). Raises <code>creatingUser</code> (cancel -&gt; <code>false</code>). Calls <code>provider.createUser(userName, password, email || undefined, question || undefined, answer || undefined, !disableCreatedUser)</code>. <code>Success</code> + <code>user</code>: stores <code>user</code>, step <code>&quot;Complete&quot;</code>, clears <code>password</code>/<code>confirmPassword</code>, raises <code>createdUser</code>, <code>true</code>. Otherwise sets <code>failureMessage</code> (see message mapping in 3.2), raises <code>createUserError</code>, <code>false</code>. <strong>Does not log the new user in.</strong></td></tr><tr><td><code>continue()</code></td><td><code>void</code></td><td>no</td><td>Raises <code>continueButtonClick</code>.</td></tr><tr><td><code>reset()</code></td><td><code>void</code></td><td>no</td><td>Clears everything (all fields, user, step) back to <code>&quot;CreateUser&quot;</code>.</td></tr><tr><td><code>getState()</code></td><td><code>CreateUserWizardState</code></td><td>no</td><td><code>{ activeStep, userName, email, question, answer, validationErrors, failureMessage, isComplete, user, continueDestinationPageUrl? }</code>. (Does not call <code>validate()</code>, unlike other <code>getState</code>s.)</td></tr></tbody></table></div>\n<p><strong>Events</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>creatingUser</code></td><td><code>CreateUserCancelEventArgs</code> <code>{ userName, password, email?, cancel }</code></td><td>yes</td><td>After validation, before the provider call.</td><td><code>cancel</code> only (edits to other fields are ignored)</td></tr><tr><td><code>createdUser</code></td><td><code>IUser</code></td><td>no</td><td>After provider <code>Success</code>.</td><td>none</td></tr><tr><td><code>createUserError</code></td><td><code>string</code></td><td>no</td><td>After a non-success result.</td><td>none</td></tr><tr><td><code>continueButtonClick</code></td><td><code>void</code></td><td>no</td><td><code>continue()</code>.</td><td>none</td></tr><tr><td><code>stateChanged</code></td><td><code>CreateUserWizardState</code></td><td>no</td><td>Setters, success, failure, validation failure, <code>reset()</code>.</td><td>none</td></tr></tbody></table></div>\n<p><strong>Example</strong></p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> p = <span class=\"tok-k\">new</span> <span class=\"tok-t\">InMemoryAuthProvider</span>({ users: [{ userName: <span class=\"tok-s\">&quot;alice&quot;</span>, password: <span class=\"tok-s\">&quot;oldpw&quot;</span>, email: <span class=\"tok-s\">&quot;alice@x.com&quot;</span>, roles: [<span class=\"tok-s\">&quot;Users&quot;</span>] }] });\n<span class=\"tok-k\">const</span> w = <span class=\"tok-k\">new</span> <span class=\"tok-t\">CreateUserWizardController</span>({ provider: p });\nw.creatingUser.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;creating&quot;</span>, e.userName, e.email));\nw.createdUser.<span class=\"tok-f\">subscribe</span>((s, u) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;created&quot;</span>, u.userName, u.roles, u.isApproved));\nw.createUserError.<span class=\"tok-f\">subscribe</span>((s, m) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;error:&quot;</span>, m));\n\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> w.<span class=\"tok-f\">createUser</span>(), w.validationErrors);\n<span class=\"tok-c\">// -&gt; false [ 'User Name is required.', 'Password is required.', 'E-mail is required.' ]</span>\n<span class=\"tok-t\">Object</span>.<span class=\"tok-f\">assign</span>(w, { userName: <span class=\"tok-s\">&quot;alice&quot;</span>, password: <span class=\"tok-s\">&quot;pw12&quot;</span>, confirmPassword: <span class=\"tok-s\">&quot;pw12&quot;</span>, email: <span class=\"tok-s\">&quot;z@x.com&quot;</span> });\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> w.<span class=\"tok-f\">createUser</span>());     <span class=\"tok-c\">// -&gt; creating alice z@x.com / error: Please enter a different user name. / false</span>\n<span class=\"tok-t\">Object</span>.<span class=\"tok-f\">assign</span>(w, { userName: <span class=\"tok-s\">&quot;carol&quot;</span>, email: <span class=\"tok-s\">&quot;ALICE@x.com&quot;</span> });\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> w.<span class=\"tok-f\">createUser</span>());     <span class=\"tok-c\">// -&gt; ... error: A user name already exists to authorize this e-mail address. ... / false</span>\n<span class=\"tok-t\">Object</span>.<span class=\"tok-f\">assign</span>(w, { userName: <span class=\"tok-s\">&quot;carol&quot;</span>, email: <span class=\"tok-s\">&quot;carol@x.com&quot;</span>, question: <span class=\"tok-s\">&quot;Q&quot;</span>, answer: <span class=\"tok-s\">&quot;A&quot;</span> });\nw.disableCreatedUser = <span class=\"tok-k\">true</span>;\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> w.<span class=\"tok-f\">createUser</span>(), w.activeStep, w.user?.userName);\n<span class=\"tok-c\">// -&gt; creating carol carol@x.com / created carol [ 'User' ] false / true Complete carol</span>\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> p.<span class=\"tok-f\">login</span>(<span class=\"tok-s\">&quot;carol&quot;</span>, <span class=\"tok-s\">&quot;pw12&quot;</span>));   <span class=\"tok-c\">// -&gt; false (unapproved)</span></code></pre></div>\n<hr>\n"},"writing-a-custom-rest-provider":{"overview":"<p>Implement all 13 members. The fake <code>fakeFetch</code> below stands in for <code>fetch(&quot;/api/...&quot;)</code>; replace it with your HTTP calls. Run end to end against the built output.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">import</span> {\n  <span class=\"tok-t\">SecurityManager</span>, <span class=\"tok-t\">IMembershipProvider</span>, <span class=\"tok-t\">IUser</span>, <span class=\"tok-t\">MembershipCreateResult</span>,\n  <span class=\"tok-t\">LoginController</span>, <span class=\"tok-t\">LoginViewController</span>, <span class=\"tok-t\">LoginNameController</span>,\n  <span class=\"tok-t\">ChangePasswordController</span>, <span class=\"tok-t\">PasswordRecoveryController</span>, <span class=\"tok-t\">CreateUserWizardController</span>,\n} <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n\n<span class=\"tok-k\">class</span> <span class=\"tok-t\">RestMembershipProvider</span> <span class=\"tok-k\">implements</span> <span class=\"tok-t\">IMembershipProvider</span> {\n  <span class=\"tok-k\">readonly</span> name = <span class=\"tok-s\">&quot;RestMembershipProvider&quot;</span>;\n  #current: <span class=\"tok-t\">IUser</span> | <span class=\"tok-k\">null</span> = <span class=\"tok-k\">null</span>;                      <span class=\"tok-c\">// session cache (sync API needs it)</span>\n\n  <span class=\"tok-k\">async</span> <span class=\"tok-f\">validateUser</span>(userName: string, password: string): <span class=\"tok-t\">Promise</span>&lt;boolean&gt; {\n    <span class=\"tok-k\">const</span> r = <span class=\"tok-k\">await</span> <span class=\"tok-f\">http</span>(<span class=\"tok-s\">&quot;POST&quot;</span>, <span class=\"tok-s\">`/api/users/${userName}/login`</span>, { password });\n    <span class=\"tok-k\">return</span> r.status === <span class=\"tok-n\">200</span>;\n  }\n  <span class=\"tok-k\">async</span> <span class=\"tok-f\">getUser</span>(userName: string): <span class=\"tok-t\">Promise</span>&lt;<span class=\"tok-t\">IUser</span> | <span class=\"tok-k\">null</span>&gt; {\n    <span class=\"tok-k\">const</span> r = <span class=\"tok-k\">await</span> <span class=\"tok-f\">http</span>(<span class=\"tok-s\">&quot;GET&quot;</span>, <span class=\"tok-s\">`/api/users/${userName}`</span>);\n    <span class=\"tok-k\">return</span> r.status === <span class=\"tok-n\">200</span> ? (r.json <span class=\"tok-k\">as</span> <span class=\"tok-t\">IUser</span>) : <span class=\"tok-k\">null</span>;\n  }\n  <span class=\"tok-f\">getCurrentUser</span>(): <span class=\"tok-t\">IUser</span> | <span class=\"tok-k\">null</span> {\n    <span class=\"tok-k\">return</span> <span class=\"tok-k\">this</span>.#current ? <span class=\"tok-f\">structuredClone</span>(<span class=\"tok-k\">this</span>.#current) : <span class=\"tok-k\">null</span>;   <span class=\"tok-c\">// sync + cheap + copy</span>\n  }\n  <span class=\"tok-k\">async</span> <span class=\"tok-f\">createUser</span>(userName: string, password: string, email?: string, passwordQuestion?: string,\n                   passwordAnswer?: string, isApproved: boolean = <span class=\"tok-k\">true</span>): <span class=\"tok-t\">Promise</span>&lt;<span class=\"tok-t\">MembershipCreateResult</span>&gt; {\n    <span class=\"tok-k\">const</span> r = <span class=\"tok-k\">await</span> <span class=\"tok-f\">http</span>(<span class=\"tok-s\">&quot;POST&quot;</span>, <span class=\"tok-s\">&quot;/api/users&quot;</span>, { userName, password, email, question: passwordQuestion, answer: passwordAnswer, isApproved });\n    <span class=\"tok-k\">if</span> (r.status === <span class=\"tok-n\">409</span>) <span class=\"tok-k\">return</span> { status: <span class=\"tok-s\">&quot;DuplicateUserName&quot;</span>, errorMessage: <span class=\"tok-s\">&quot;Conflict&quot;</span> };\n    <span class=\"tok-k\">if</span> (r.status !== <span class=\"tok-n\">201</span>) <span class=\"tok-k\">return</span> { status: <span class=\"tok-s\">&quot;ProviderError&quot;</span>, errorMessage: <span class=\"tok-s\">`HTTP ${r.status}`</span> };\n    <span class=\"tok-k\">return</span> { status: <span class=\"tok-s\">&quot;Success&quot;</span>, user: (<span class=\"tok-k\">await</span> <span class=\"tok-k\">this</span>.<span class=\"tok-f\">getUser</span>(userName))! };\n  }\n  <span class=\"tok-k\">async</span> <span class=\"tok-f\">changePassword</span>(userName: string, oldPassword: string, newPassword: string): <span class=\"tok-t\">Promise</span>&lt;boolean&gt; {\n    <span class=\"tok-k\">return</span> (<span class=\"tok-k\">await</span> <span class=\"tok-f\">http</span>(<span class=\"tok-s\">&quot;POST&quot;</span>, <span class=\"tok-s\">`/api/users/${userName}/password`</span>, { oldPassword, newPassword })).status === <span class=\"tok-n\">204</span>;\n  }\n  <span class=\"tok-k\">async</span> <span class=\"tok-f\">resetPassword</span>(userName: string, answer?: string): <span class=\"tok-t\">Promise</span>&lt;string | <span class=\"tok-k\">null</span>&gt; {\n    <span class=\"tok-k\">const</span> r = <span class=\"tok-k\">await</span> <span class=\"tok-f\">http</span>(<span class=\"tok-s\">&quot;POST&quot;</span>, <span class=\"tok-s\">`/api/users/${userName}/reset`</span>, { answer });\n    <span class=\"tok-k\">return</span> r.status === <span class=\"tok-n\">200</span> ? (r.json <span class=\"tok-k\">as</span> any).temporaryPassword : <span class=\"tok-k\">null</span>;\n  }\n  <span class=\"tok-k\">async</span> <span class=\"tok-f\">getPasswordQuestion</span>(userName: string): <span class=\"tok-t\">Promise</span>&lt;string | <span class=\"tok-k\">null</span>&gt; {\n    <span class=\"tok-k\">return</span> (<span class=\"tok-k\">await</span> <span class=\"tok-k\">this</span>.<span class=\"tok-f\">getUser</span>(userName))?.passwordQuestion ?? <span class=\"tok-k\">null</span>;\n  }\n  <span class=\"tok-k\">async</span> <span class=\"tok-f\">unlockUser</span>(userName: string): <span class=\"tok-t\">Promise</span>&lt;boolean&gt; {\n    <span class=\"tok-k\">return</span> (<span class=\"tok-k\">await</span> <span class=\"tok-f\">http</span>(<span class=\"tok-s\">&quot;POST&quot;</span>, <span class=\"tok-s\">`/api/users/${userName}/unlock`</span>)).status === <span class=\"tok-n\">204</span>;\n  }\n  <span class=\"tok-k\">async</span> <span class=\"tok-f\">login</span>(userName: string, password: string, rememberMe: boolean = <span class=\"tok-k\">false</span>): <span class=\"tok-t\">Promise</span>&lt;boolean&gt; {\n    <span class=\"tok-k\">if</span> (!(<span class=\"tok-k\">await</span> <span class=\"tok-k\">this</span>.<span class=\"tok-f\">validateUser</span>(userName, password))) <span class=\"tok-k\">return</span> <span class=\"tok-k\">false</span>;\n    <span class=\"tok-k\">this</span>.#current = <span class=\"tok-k\">await</span> <span class=\"tok-k\">this</span>.<span class=\"tok-f\">getUser</span>(userName);     <span class=\"tok-c\">// persist token / rememberMe here if desired</span>\n    <span class=\"tok-t\">SecurityManager</span>.<span class=\"tok-f\">notifyCurrentUserChanged</span>(<span class=\"tok-k\">this</span>.<span class=\"tok-f\">getCurrentUser</span>());   <span class=\"tok-c\">// REQUIRED</span>\n    <span class=\"tok-k\">return</span> <span class=\"tok-k\">true</span>;\n  }\n  <span class=\"tok-k\">async</span> <span class=\"tok-f\">logout</span>(): <span class=\"tok-t\">Promise</span>&lt;<span class=\"tok-k\">void</span>&gt; {\n    <span class=\"tok-k\">this</span>.#current = <span class=\"tok-k\">null</span>;\n    <span class=\"tok-t\">SecurityManager</span>.<span class=\"tok-f\">notifyCurrentUserChanged</span>(<span class=\"tok-k\">null</span>);                    <span class=\"tok-c\">// REQUIRED</span>\n  }\n  <span class=\"tok-f\">isInRole</span>(role: string, userName?: string): boolean {\n    <span class=\"tok-k\">return</span> <span class=\"tok-k\">this</span>.<span class=\"tok-f\">getRolesForUser</span>(userName).<span class=\"tok-f\">some</span>((r) =&gt; r.<span class=\"tok-f\">toLowerCase</span>() === role.<span class=\"tok-f\">toLowerCase</span>());\n  }\n  <span class=\"tok-f\">getRolesForUser</span>(userName?: string): string[] {\n    <span class=\"tok-c\">// Synchronous API: only the current user's roles are known without a round trip.</span>\n    <span class=\"tok-k\">if</span> (userName &amp;&amp; userName.<span class=\"tok-f\">toLowerCase</span>() !== <span class=\"tok-k\">this</span>.#current?.userName.<span class=\"tok-f\">toLowerCase</span>()) <span class=\"tok-k\">return</span> [];\n    <span class=\"tok-k\">return</span> <span class=\"tok-k\">this</span>.#current?.roles ? [...<span class=\"tok-k\">this</span>.#current.roles] : [];\n  }\n}\n\n<span class=\"tok-k\">const</span> provider = <span class=\"tok-k\">new</span> <span class=\"tok-t\">RestMembershipProvider</span>();\n<span class=\"tok-t\">SecurityManager</span>.<span class=\"tok-f\">setProvider</span>(provider);        <span class=\"tok-c\">// BEFORE constructing controllers</span>\n\n<span class=\"tok-k\">const</span> view = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginViewController</span>({ anonymousTemplate: <span class=\"tok-s\">&quot;anon&quot;</span>, loggedInTemplate: <span class=\"tok-s\">&quot;member&quot;</span>,\n                                       roleGroups: [{ roles: [<span class=\"tok-s\">&quot;Managers&quot;</span>], contentTemplate: <span class=\"tok-s\">&quot;mgr&quot;</span> }] });\nview.viewChanged.<span class=\"tok-f\">subscribe</span>((s, v) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;view -&gt;&quot;</span>, v.<span class=\"tok-k\">type</span>, v.template));\n<span class=\"tok-k\">const</span> name = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginNameController</span>();\n<span class=\"tok-k\">const</span> login = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginController</span>({ userName: <span class=\"tok-s\">&quot;alice&quot;</span>, password: <span class=\"tok-s\">&quot;bad&quot;</span> });\n\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> login.<span class=\"tok-f\">login</span>());                                   <span class=\"tok-c\">// -&gt; false</span>\nlogin.password = <span class=\"tok-s\">&quot;s3cret!&quot;</span>;\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> login.<span class=\"tok-f\">login</span>(), name.formattedText, provider.<span class=\"tok-f\">isInRole</span>(<span class=\"tok-s\">&quot;managers&quot;</span>));\n<span class=\"tok-c\">// -&gt; view -&gt; RoleGroup mgr</span>\n<span class=\"tok-c\">// -&gt; true Welcome, alice true</span>\n\n<span class=\"tok-k\">const</span> cp = <span class=\"tok-k\">new</span> <span class=\"tok-t\">ChangePasswordController</span>({ currentPassword: <span class=\"tok-s\">&quot;s3cret!&quot;</span>, newPassword: <span class=\"tok-s\">&quot;N3wpass&quot;</span>, confirmNewPassword: <span class=\"tok-s\">&quot;N3wpass&quot;</span> });\nconsole.<span class=\"tok-f\">log</span>(cp.effectiveUserName, <span class=\"tok-k\">await</span> cp.<span class=\"tok-f\">changePassword</span>());       <span class=\"tok-c\">// -&gt; alice true   (user taken from getCurrentUser)</span>\n\n<span class=\"tok-k\">const</span> reg = <span class=\"tok-k\">new</span> <span class=\"tok-t\">CreateUserWizardController</span>({ userName: <span class=\"tok-s\">&quot;bob&quot;</span>, password: <span class=\"tok-s\">&quot;abcd1&quot;</span>, confirmPassword: <span class=\"tok-s\">&quot;abcd1&quot;</span>, email: <span class=\"tok-s\">&quot;bob@corp.com&quot;</span> });\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> reg.<span class=\"tok-f\">createUser</span>(), reg.user!.roles);               <span class=\"tok-c\">// -&gt; true [ 'Users' ]</span>\nreg.<span class=\"tok-f\">reset</span>(); <span class=\"tok-t\">Object</span>.<span class=\"tok-f\">assign</span>(reg, { userName: <span class=\"tok-s\">&quot;bob&quot;</span>, password: <span class=\"tok-s\">&quot;abcd1&quot;</span>, confirmPassword: <span class=\"tok-s\">&quot;abcd1&quot;</span>, email: <span class=\"tok-s\">&quot;b@c.com&quot;</span> });\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> reg.<span class=\"tok-f\">createUser</span>(), reg.failureMessage);            <span class=\"tok-c\">// -&gt; false Please enter a different user name.</span>\n\n<span class=\"tok-k\">const</span> pr = <span class=\"tok-k\">new</span> <span class=\"tok-t\">PasswordRecoveryController</span>({ userName: <span class=\"tok-s\">&quot;alice&quot;</span> });\n<span class=\"tok-k\">await</span> pr.<span class=\"tok-f\">submitUserName</span>(); pr.answer = <span class=\"tok-s\">&quot;OSLO&quot;</span>;\npr.sendingMail.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;mail to&quot;</span>, e.recipientEmail, e.newPassword));\nconsole.<span class=\"tok-f\">log</span>(pr.question, <span class=\"tok-k\">await</span> pr.<span class=\"tok-f\">submitAnswer</span>());\n<span class=\"tok-c\">// -&gt; mail to alice@corp.com Tmp-1234</span>\n<span class=\"tok-c\">// -&gt; City? true</span>\n<span class=\"tok-k\">await</span> provider.<span class=\"tok-f\">logout</span>();                                            <span class=\"tok-c\">// -&gt; view -&gt; Anonymous anon</span></code></pre></div>\n<p>(<code>http</code>/<code>fakeFetch</code> is any function returning <code>{ status, json }</code>; the verified script used an in-memory fake backend with the same routes. Because the provider's <code>#current</code> is a JS private field, it works under <code>target: ES2022</code>.)</p>\n<p>Checklist for a production provider: hash/verify passwords <strong>server-side</strong> (never in the browser), keep tokens in <code>HttpOnly</code> cookies where possible, make <code>resetPassword</code> send the mail server-side and return a non-sensitive value or a sentinel, restore the session into <code>#current</code> on start-up (then call <code>notifyCurrentUserChanged</code>), and keep <code>getCurrentUser()</code> synchronous.</p>\n<hr>\n"},"more-examples":{"examples":"<ul class=\"aa-doc-index\"><li><a href=\"#/api/security/more-examples/examples/121-guard-a-route-by-role\">Guard a route by role</a></li><li><a href=\"#/api/security/more-examples/examples/122-use-authenticate-for-step-up-verification\">Use authenticate() for step-up verification</a></li><li><a href=\"#/api/security/more-examples/examples/123-disable-remember-me-ui\">Disable \"remember me\" UI</a></li><li><a href=\"#/api/security/more-examples/examples/124-re-pointing-controllers-after-setprovider\">Re-pointing controllers after setProvider</a></li></ul><h3 id=\"121-guard-a-route-by-role\">12.1 Guard a route by role<a class=\"anchor\" href=\"#121-guard-a-route-by-role\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> provider = <span class=\"tok-t\">SecurityManager</span>.defaultProvider;\n<span class=\"tok-k\">await</span> provider.<span class=\"tok-f\">login</span>(<span class=\"tok-s\">&quot;user&quot;</span>, <span class=\"tok-s\">&quot;Password123!&quot;</span>);\nconsole.<span class=\"tok-f\">log</span>(provider.<span class=\"tok-f\">isInRole</span>(<span class=\"tok-s\">&quot;administrators&quot;</span>), provider.<span class=\"tok-f\">isInRole</span>(<span class=\"tok-s\">&quot;USERS&quot;</span>), provider.<span class=\"tok-f\">getRolesForUser</span>());\n<span class=\"tok-c\">// -&gt; false true [ 'Users' ]</span></code></pre></div>\n<p>(<code>isInRole</code> is case-insensitive.)</p>\n<h3 id=\"122-use-authenticate-for-step-up-verification\">12.2 Use <code>authenticate()</code> for step-up verification<a class=\"anchor\" href=\"#122-use-authenticate-for-step-up-verification\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> l = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginController</span>({ userName: <span class=\"tok-s\">&quot;admin&quot;</span>, password: <span class=\"tok-s\">&quot;Password123!&quot;</span> });\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> l.<span class=\"tok-f\">authenticate</span>(), <span class=\"tok-t\">SecurityManager</span>.defaultProvider.<span class=\"tok-f\">getCurrentUser</span>());\n<span class=\"tok-c\">// -&gt; true null     (credentials valid, but no session was created)</span></code></pre></div>\n<h3 id=\"123-disable-remember-me-ui\">12.3 Disable &quot;remember me&quot; UI<a class=\"anchor\" href=\"#123-disable-remember-me-ui\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> login = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginController</span>({ displayRememberMe: <span class=\"tok-k\">false</span> });\nconsole.<span class=\"tok-f\">log</span>(login.<span class=\"tok-f\">getState</span>().displayRememberMe);   <span class=\"tok-c\">// -&gt; false</span></code></pre></div>\n<h3 id=\"124-re-pointing-controllers-after-setprovider\">12.4 Re-pointing controllers after <code>setProvider</code><a class=\"anchor\" href=\"#124-re-pointing-controllers-after-setprovider\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> lc = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginController</span>({ userName: <span class=\"tok-s\">&quot;admin&quot;</span>, password: <span class=\"tok-s\">&quot;Password123!&quot;</span> });\n<span class=\"tok-k\">await</span> lc.<span class=\"tok-f\">login</span>();\n<span class=\"tok-t\">SecurityManager</span>.<span class=\"tok-f\">setProvider</span>(<span class=\"tok-k\">new</span> <span class=\"tok-t\">InMemoryAuthProvider</span>({ name: <span class=\"tok-s\">&quot;Other&quot;</span> }));\nconsole.<span class=\"tok-f\">log</span>(lc.isLoggedIn, <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginController</span>().isLoggedIn);   <span class=\"tok-c\">// -&gt; true false</span></code></pre></div>\n<hr>\n"},"gotchas-and-known-inconsistencies":{"overview":"<ul><li><strong>No <code>authenticate</code> event or step in <code>login()</code></strong>: <code>authenticate()</code> is a separate helper (section 2.7).</li><li><strong>Plain-text passwords</strong> in <code>InMemoryAuthProvider</code>; temporary passwords are generated with <code>Math.random</code>.</li><li><strong><code>rememberMe</code> is inert</strong> in the built-in provider; no storage (cookie/<code>localStorage</code>) exists in core.</li><li><strong>Existing controllers keep the provider captured at construction.</strong></li><li><strong>Custom providers must call <code>SecurityManager.notifyCurrentUserChanged</code>.</strong></li><li><strong><code>getState()</code> side effects</strong> in <code>LoginController</code> and <code>ChangePasswordController</code> (re-runs <code>validate()</code>).</li><li><strong>Unawaited <code>stateChanged</code>/<code>viewChanged</code>/<code>continueButtonClick</code> emissions</strong>: an exception thrown by an async handler of these events becomes an unhandled rejection rather than failing the operation.</li><li><strong><code>PasswordRecoveryController.sendingMail</code> cancel</strong> does not roll back the provider reset.</li><li><strong><code>MembershipCreateStatus</code> values</strong> <code>InvalidQuestion</code>, <code>InvalidAnswer</code>, <code>InvalidEmail</code>, <code>UserRejected</code>, <code>ProviderError</code> have no special handling in the wizard (message comes from <code>errorMessage</code>).</li><li><strong><code>validationGroup</code>, <code>destinationPageUrl</code>, <code>logoutAction</code>, <code>continueDestinationPageUrl</code>, <code>*Url</code>/<code>*Text</code> link options</strong> are data only; adapters must act on them.</li><li><strong>Case/trim asymmetry</strong> in <code>InMemoryAuthProvider</code>: <code>createUser</code> trims the user name; lookups (<code>validateUser</code>, <code>getUser</code>, ...) only lower-case it.</li></ul>\n<hr>\n"},"authentication-and-authorization-free-in-core-forms-url-authorization-in-enterprise-security":{"overview":"<p>Headless. Free pieces (principals, roles, <code>PasswordPolicy</code>, <code>authorizeControl</code>, <code>CurrentPrincipal</code>) live in <code>packages/core/src/security/</code>; Enterprise pieces (<code>FormsAuthentication</code>, <code>UrlAuthorization</code>, Windows/SSO/JWT, <code>RestMembershipProvider</code>) live in <code>packages/enterprise-security/</code>. Tests: <code>packages/core/test/principal-roles.test.mjs</code>, <code>packages/enterprise-security/test/</code>.</p>\n<div class=\"table-scroll\"><table><thead><tr><th>ASP.NET</th><th>Here</th><th>Notes</th></tr></thead><tbody><tr><td><code>IPrincipal</code> / <code>IIdentity</code> / <code>GenericPrincipal</code></td><td>same names</td><td><code>AnonymousPrincipal</code> for signed-out users; <code>WindowsLikeIdentity</code> exposes <code>domain</code> / <code>userName</code> of a server-reported <code>DOMAIN\\user</code>.</td></tr><tr><td><code>HttpContext.User</code></td><td><code>CurrentPrincipal.current</code> / <code>.set()</code> / <code>.subscribe()</code></td><td>Follows <code>SecurityManager</code> automatically; <code>.set()</code> overrides it with a server-supplied identity.</td></tr><tr><td><code>Roles</code> / <code>RoleProvider</code></td><td><code>Roles</code>, <code>IRoleProvider</code>, <code>InMemoryRoleProvider</code></td><td>Create/delete roles, add/remove users, <code>isUserInRole</code>, <code>findUsersInRole</code>.</td></tr><tr><td><code>FormsAuthentication</code></td><td><code>FormsAuthentication</code></td><td><code>setAuthCookie</code>, <code>signOut</code>, <code>getTicket</code>, <code>getPrincipal</code>, <code>redirectFromLoginPage</code>, <code>redirectToLoginPage</code>, <code>configure</code>. Events <code>authenticating</code> (cancellable), <code>authenticated</code>, <code>signedOut</code>. Storage (<code>IAuthStorage</code>), clock (<code>now</code>) and redirect (<code>onRedirect</code>) are injected, so core stays DOM-free. Sliding expiration renews after half the timeout.</td></tr><tr><td><code>&lt;authorization&gt;</code> / <code>&lt;location&gt;</code></td><td><code>UrlAuthorization</code>, <code>AuthorizationConfig</code></td><td><code>*</code> all, <code>?</code> anonymous, <code>@</code> authenticated, role names, optional verbs. <code>/path/*</code> and <code>/path/**</code> patterns.</td></tr><tr><td><code>Login.DestinationPageUrl</code> + <code>ReturnUrl</code></td><td><code>LoginOptions.postLogin</code> (<code>formsLoginHook()</code> from enterprise-security), <code>returnUrl</code></td><td>Off by default. Unsafe URLs (<code>//host</code>, <code>http:</code>, <code>javascript:</code>, backslashes, control characters) fall back to <code>defaultUrl</code>.</td></tr><tr><td><code>Membership</code> password rules</td><td><code>PasswordPolicy</code></td><td>Pass to <code>InMemoryAuthProvider({ passwordPolicy })</code>.</td></tr><tr><td>Custom/remote providers</td><td><code>RestMembershipProvider</code>, <code>decodeJwt</code>, <code>OidcPrincipalFactory</code></td><td><code>fetchFn</code> is injected. JWT decoding does NOT verify signatures.</td></tr></tbody></table></div>\n<p><strong>Limits.</strong> Windows/Integrated authentication (NTLM, Kerberos) happens on a server; a browser cannot perform it. Have the server expose a &quot;who am I&quot; endpoint and feed the result to <code>OidcPrincipalFactory.fromWindowsIdentity</code> and <code>CurrentPrincipal.set</code>. All client-side authorization is UX only. The server must enforce the same rules.</p>"}};
export default area;
